/* Grundwissen: eigene interaktive Modelle. Keine externen Bibliotheken.
   controls: range unless options exists; render(values) returns an HTML fragment.
   B02 and T01 deliberately preserve the already approved visualisations. */
const DISCOVERIES = (() => {
  'use strict';
  const D = {}, ink = '#355a70', tint = '#dce8ed', alt = '#a96527', pale = '#f4e8d9';
  const e = x => String(x).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const f = (x, digits = 3) => (Math.abs(x) < 1e-10 ? 0 : +x.toFixed(digits)).toLocaleString('de-DE');
  const gcd = (a,b) => b ? gcd(b,a%b) : Math.abs(a);
  const frac = (a,b) => `${a}/${b}`;
  const reduced = (a,b) => { if(b<0){a=-a;b=-b;} const g=gcd(a,b); return b/g===1 ? `${a/g}` : frac(a/g,b/g); };
  const r = (key,label,min,max,value,step=1) => ({key,label,min,max,value,step});
  const opt = (key,label,values,value=values[0][0]) => ({key,label,value,options:values.map(([value,label])=>({value,label}))});
  const tx = (x,y,text,size=16,color='#25323a',anchor='middle') => /(?:[0-9a-zUV)]\s*\/|\^)/.test(String(text)) ? notationSVG(x,y,text,size,color,anchor) : `<text x="${x}" y="${y}" font-size="${size}" fill="${color}" text-anchor="${anchor}" dominant-baseline="middle">${e(text)}</text>`;
  const ln = (x1,y1,x2,y2,color=ink,width=2,dash='') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
  const rect = (x,y,w,h,fill=tint,stroke=ink) => `<rect x="${x}" y="${y}" width="${Math.max(0,w)}" height="${Math.max(0,h)}" fill="${fill}" stroke="${stroke}"/>`;
  const circle = (x,y,r,color=ink) => '<circle data-construction-circle="true" cx="'+x+'" cy="'+y+'" r="'+r+'" fill="none" stroke="'+color+'" stroke-width="2"/>';
  const dot = (x,y,fill=ink,rad=5) => `<circle cx="${x}" cy="${y}" r="${rad}" fill="${fill}"/>`;
  const poly = (pts,fill=tint,stroke=ink) => `<polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;
  const svg = (body,label,h=260) => `<svg class="discovery-svg" role="img" aria-label="${e(label)}" viewBox="0 0 600 ${h}" style="display:block;width:100%;max-height:360px;font-family:inherit;overflow:visible">${body}</svg>`;
  const statement = (formula,text='') => `<p class="discovery-equation" style="font-size:1.2rem;font-weight:650;text-align:center">${notationHTML(formula)}</p>${text?`<p class="discovery-observation">${notationHTML(text)}</p>`:''}`;
  const table = (headers,rows) => `<div style="overflow:auto"><table class="discovery-table" style="width:100%;border-collapse:collapse;text-align:center"><thead><tr>${headers.map(x=>`<th scope="col" style="padding:8px;border-bottom:1px solid #ccc">${notationMaterial(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td style="padding:8px;border-bottom:1px solid #e3e6e7">${notationHTML(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  function add(id,controls,question,explanation,renderer,invariant,bounds) {
    D[id]={controls,question,explanation,invariant,bounds,render(raw={}){
      const v={}; for(const c of controls){let x=raw[c.key]??c.value;if(c.options){v[c.key]=c.options.some(o=>String(o.value)===String(x))?x:c.value;}else {x=Number(x);v[c.key]=Number.isFinite(x)?Math.max(c.min,Math.min(c.max,x)):c.value;}}
      return `<div class="discovery-model">${renderer(v)}</div>`;
    }};
  }
  function numberLine(points,min,max,arrows=[],options={}){
    const X=v=>45+(v-min)/(max-min)*510,major=options.step||PlotScale.step(min,max,12),minor=options.minor||PlotScale.minor(major,Math.min(1,major/2));let s=ln(45,150,555,150);for(const n of PlotScale.ticks(min,max,minor)){const labeled=PlotScale.isMajor(n,major);s+=ln(X(n),labeled?143:146,X(n),labeled?157:154,'#8b969c',1);if(labeled)s+=`<g data-axis="number" data-tick="${n}">${tx(X(n),178,f(n),12)}</g>`;}
    arrows.forEach((a,i)=>{let y=100-i*35,x1=X(a[0]),x2=X(a[1]),c=a[3]||ink;s+=ln(x1,y,x2,y,c,3)+poly([[x2,y],[x2+(x2>=x1?-8:8),y-5],[x2+(x2>=x1?-8:8),y+5]],c,c)+tx((x1+x2)/2,y-15,a[2],14,c);});
    points.forEach((p,i)=>s+=ln(X(p[0]),125,X(p[0]),150,p[2]||ink,1,'3 3')+dot(X(p[0]),150,p[2]||ink)+tx(X(p[0]),210+(i%2)*24,p[1],15,p[2]||ink));return svg(s,'Zahlenstrahl: '+points.map(p=>p[1]).join(', '),250);
  }
  function bar(n,d,y=65,label='',color=ink,x=65,w=470){let s='';for(let i=0;i<d;i++)s+=rect(x+i*w/d,y,w/d,38,i<n?(color===ink?tint:pale):'#fff',color);return s+tx(x+w/2,y-18,label,16,color);}
  function grid(nx,ny,selected=(x,y)=>true,w=360,h=180,x0=120,y0=45){let s='';for(let y=0;y<ny;y++)for(let x=0;x<nx;x++)s+=rect(x0+x*w/nx,y0+y*h/ny,w/nx,h/ny,selected(x,y)?tint:'#fff','#8ba0ac');return s;}
  function graph(series,points=[],range=[-5,5,-5,5],extra='',options={}){
    const [xmin,xmax,ymin,ymax]=range,square=range[4]==='square',height=options.height||220,center=30+height/2,scale=Math.min(500/(xmax-xmin),height/(ymax-ymin)),left=square?300-(xmax-xmin)*scale/2:50,right=square?300+(xmax-xmin)*scale/2:550,top=square?center-(ymax-ymin)*scale/2:30,bottom=square?center+(ymax-ymin)*scale/2:30+height,X=x=>left+(x-xmin)/(xmax-xmin)*(right-left),Y=y=>bottom-(y-ymin)/(ymax-ymin)*(bottom-top);
    const xStep=options.xStep||Math.max(1,PlotScale.step(xmin,xmax,10)),yStep=options.yStep||Math.max(1,PlotScale.step(ymin,ymax,8)),xMinor=options.xMinor||PlotScale.minor(xStep),yMinor=options.yMinor||PlotScale.minor(yStep);let s='';for(const x of PlotScale.ticks(xmin,xmax,xMinor)){const major=PlotScale.isMajor(x,xStep);s+=ln(X(x),top,X(x),bottom,major?'#dce3e7':'#edf1f3',1);if(major)s+=`<g data-axis="x" data-tick="${x}">${tx(X(x),bottom+22,f(x),12)}</g>`;}for(const y of PlotScale.ticks(ymin,ymax,yMinor)){const major=PlotScale.isMajor(y,yStep);s+=ln(left,Y(y),right,Y(y),major?'#dce3e7':'#edf1f3',1);if(major)s+=`<g data-axis="y" data-tick="${y}">${tx(left-20,Y(y),f(y),12)}</g>`;}
    if(xmin<=0&&xmax>=0)s+=ln(X(0),top,X(0),bottom,'#89979e');if(ymin<=0&&ymax>=0)s+=ln(left,Y(0),right,Y(0),'#89979e');s+=options.xLabel?tx(300,bottom+46,options.xLabel,14):tx(right+20,bottom+3,'x',14);s+=options.yLabel?tx(left,top-17,options.yLabel,14,ink,'start'):tx(left,top-17,'y',14);
    series.forEach((q,k)=>{let seg=[];const flush=()=>{if(seg.length>1)s+=`<polyline points="${seg.join(' ')}" fill="none" stroke="${q.color||(k?alt:ink)}" stroke-width="3" ${q.dash?'stroke-dasharray="6 4"':''}/>`;seg=[];};for(let i=0;i<=240;i++){let x=xmin+(xmax-xmin)*i/240,y=q.fn(x);if(!Number.isFinite(y)||y<ymin||y>ymax){flush();continue;}seg.push(`${X(x)},${Y(y)}`);}flush();});
    if(typeof extra==='function')s+=extra(X,Y);
    const marked=[];for(const p of points){const same=marked.find(q=>Math.abs(q[0]-p[0])<1e-9&&Math.abs(q[1]-p[1])<1e-9);if(same){if(p[2]&&p[2]!==same[2])same[2]=[same[2],p[2]].filter(Boolean).join(' / ');}else marked.push([...p]);}
    marked.forEach(p=>{if(p[0]>=xmin&&p[0]<=xmax&&p[1]>=ymin&&p[1]<=ymax)s+=dot(X(p[0]),Y(p[1]),p[3]||ink)+tx(X(p[0])+8,Y(p[1])-12,p[2]||'',13,p[3]||ink,'start');});
    return svg(s,'Koordinatensystem mit veränderbaren Graphen und markierten Punkten',height+(options.xLabel?100:75));
  }
  const geometryGraph=(series,points,range,extra)=>graph(series,points,[...range,'square'],extra);
  function barAxis(max,bottom,scale,step){return ln(52,bottom,550,bottom,'#8b969c',1)+PlotScale.ticks(0,max,step).map(n=>`<g data-axis="value" data-tick="${n}">${ln(52,bottom-n*scale,550,bottom-n*scale,'#e3e8eb',1)}${tx(38,bottom-n*scale,String(n),12)}</g>`).join('');}

  add('N01',[r('n','Zahl',43600,43700,43674),opt('unit','Runden auf',[[10,'Zehner'],[100,'Hunderter']],100)],'An welcher Zahl kippt die Rundung zum oberen Nachbarn?','Runden bedeutet: den näheren Nachbarn wählen. Die Mitte gehört zum oberen Nachbarn.',v=>{let u=+v.unit,lo=Math.floor(v.n/u)*u,hi=lo+u,m=(lo+hi)/2,res=Math.round(v.n/u)*u;return numberLine([[v.n,f(v.n)],[m,'Mitte '+f(m),alt]],lo,hi)+statement(`${f(v.n)} ≈ ${f(res)}`,`Abstand nach unten: ${f(v.n-lo)}. Abstand nach oben: ${f(hi-v.n)}.`);},'Die Rundungsstelle legt die Nachbarn fest; nur die Lage der Zahl entscheidet.','Ganzzahlige Zahlen; exakte Mitte wird aufgerundet.');
  add('N02',[r('a','Erster Faktor',2,12,6),r('b','Zweiter Faktor',2,12,8)],'Was passiert mit dem Rechteck, wenn du einen Faktor verdoppelst?','Multiplikation zählt gleich große Reihen. Division fragt nach Reihenanzahl oder Reihengröße.',v=>svg(grid(v.b,v.a,()=>true,v.b*18,v.a*18,300-v.b*9,25),'Punktefeld als Produkt')+statement(`${v.a} · ${v.b} = ${v.a*v.b}`,`Umkehrung: ${v.a*v.b} : ${v.a} = ${v.b} und ${v.a*v.b} : ${v.b} = ${v.a}.`),'Jede Reihe enthält gleich viele Felder.','Positive ganze Faktoren; keine Division durch null.');
  add('N03',[r('n','Anzahl der Punkte',2,48,18),r('rows','Anzahl der Reihen',1,12,3)],'Wann lässt sich die Zahl ohne Rest zu einem Rechteck legen?','Verteile die Punkte gleichmäßig auf die gewählte Anzahl von Reihen. Was übrig bleibt, liegt getrennt darunter.',v=>{const q=Math.floor(v.n/v.rows),rest=v.n%v.rows,div=Array.from({length:v.n},(_,i)=>i+1).filter(i=>v.n%i===0),dx=Math.min(23,490/Math.max(1,q));let s=tx(300,23,q?f(v.rows)+' Reihen mit je '+f(q)+' Punkten':'Für jede Reihe wäre mindestens ein Punkt nötig.',17);for(let row=0;row<v.rows&&q;row++)for(let col=0;col<q;col++)s+=dot(55+col*dx,53+row*13,ink,Math.min(4,dx/3));s+=tx(40,230,'Rest: '+rest+' Punkte',17,alt,'start');for(let i=0;i<rest;i++)s+=dot(55+i*23,260,alt,5);return svg(s,'Gleich lange Punktreihen; Restpunkte getrennt darunter',295)+statement(v.n+' = '+v.rows+' · '+q+' + '+rest,rest?v.rows+' ist kein Teiler von '+v.n+': Es bleiben Punkte übrig.':v.rows+' ist ein Teiler von '+v.n+': Es bleibt kein Rest.')+statement('Teiler: '+div.join(', '),div.length===2?'Primzahl: Nur 1 und die Zahl selbst sind positive Teiler.':'Diese Zahl hat mehr als zwei positive Teiler.');},'Alle Punkte werden genau einmal gezeigt: in vollständigen Reihen oder als Rest.','Reihen ohne Punkte werden nicht als Rechteck ausgegeben.');
  add('N04',[r('x','Zahl in der Rechnung',1,8,3),opt('brackets','Klammer setzen',[[0,'2 + x · 4'],[1,'(2 + x) · 4']])],'Wie verändert allein die Klammer den Rechenauftrag?','Die Schreibweise legt die Reihenfolge fest; du rechnest nicht einfach von links nach rechts.',v=>{let a=v.x,b=+v.brackets;return table(['Rechenauftrag','Zuerst','Danach'],[[b?`(2 + ${a}) · 4`:`2 + ${a} · 4`,b?`2 + ${a} = ${a+2}`:`${a} · 4 = ${a*4}`,b?`${a+2} · 4 = ${(a+2)*4}`:`2 + ${a*4} = ${2+a*4}`]])+svg(b?grid(4,a+2,()=>true,72,(a+2)*18,264,45):grid(2,1,()=>true,36,18,282,35)+tx(300,77,'+',24)+grid(4,a,()=>true,72,a*18,264,100),'Klammer verändert den ersten Rechenschritt; alle Einheitsquadrate sind gleich groß',270);},'Die Zahlen und Rechenzeichen bleiben, die Klammer verändert die Struktur.','Positive kleine ganze Zahlen; Punkt-vor-Strich explizit mit Klammerfall verglichen.');
  add('N05',[r('n','Zweiter Faktor nahe 50',41,59,49),r('a','Erster Faktor',2,9,8)],'Wie hilft die nahe runde Zahl 50 beim Kopfrechnen?','Zerlege einen Faktor in eine runde Zahl und eine Korrektur. Die Korrektur wird ebenfalls mitmultipliziert.',v=>{let d=v.n-50;return svg(rect(70,70,400,v.a*8)+rect(d<0?470+d*8:470,70,Math.abs(d)*8,v.a*8,pale,alt)+tx(270,42,`${v.a} · 50 = ${v.a*50}`)+tx(48,70+v.a*4,v.a)+tx(300,200,`Korrektur ${d<0?'−':'+'} ${v.a} · ${Math.abs(d)}`,20,alt),'Rechteck für runden Faktor und Korrektur')+statement(`${v.a} · ${v.n} = ${v.a*50} ${d<0?'−':'+'} ${v.a*Math.abs(d)} = ${v.a*v.n}`);},'Der korrigierte Flächeninhalt ist gleich dem ursprünglichen Produkt.','Überschlag und exakte Korrektur werden sprachlich getrennt.');

  add('B01',[r('d','Gleich große Teile',2,10,5),r('n','Ausgewählte Teile',0,10,3)],'Was ändert der Nenner, was zählt der Zähler?','Ein Bruch bezieht sich auf ein festes Ganzes. Mehr als ein Ganzes ist möglich.',v=>{let rows=Math.ceil(v.n/v.d)||1,s='';for(let i=0;i<rows;i++)s+=bar(Math.min(v.d,Math.max(0,v.n-i*v.d)),v.d,50+i*70,i===0?'Jeder Balken ist ein Ganzes':'');return svg(s,`${v.n} von ${v.d} Teilen je Ganzem`,60+rows*70)+statement(`${v.n}/${v.d} = ${reduced(v.n,v.d)}`);},'Die Länge eines ganzen Balkens bleibt gleich.','Zähler darf größer als Nenner sein; null als Anteil erlaubt.');
  D.B02={preserveExisting:true,question:'Wie kann die Schreibweise wechseln, obwohl der Anteil gleich bleibt?',explanation:'Die bestätigte Bruchstreifen-Visualisierung bleibt erhalten.',controls:[]};
  add('B03',[r('a','Zähler des ersten Bruchs',0,6,3),r('b','Zähler des zweiten Bruchs',0,8,5),opt('fine','Einteilung',[['original','Sechstel und Achtel'],['common','Beide in Vierundzwanzigstel']])],'Wie kannst du verschieden große Bruchstücke vergleichen?','Beide Balken sind gleich große Ganze. Schalte auf Vierundzwanzigstel: Nur die Einteilung ändert sich, die markierte Menge bleibt.',v=>{const common=v.fine==='common';return svg(bar(common?v.a*4:v.a,common?24:6,65,v.a+'/6'+(common?' = '+v.a*4+'/24':''))+bar(common?v.b*3:v.b,common?24:8,155,v.b+'/8'+(common?' = '+v.b*3+'/24':''),alt),'Gleich lange Bruchstreifen mit umschaltbarer gemeinsamer Einteilung')+statement(v.a+'/6 '+(v.a*4===v.b*3?'=':v.a*4>v.b*3?'&gt;':'&lt;')+' '+v.b+'/8',common?'Jetzt haben alle kleinen Teile dieselbe Größe. Vergleiche ihre Anzahl.':'Vergleiche zunächst die markierten Längen.');},'Das Ganze und die markierten Bruchwerte bleiben beim Umeinteilen gleich.','Gemeinsamer Nenner 24; auch gleiche und leere Anteile.');
  for(const [id,sign] of [['B04',1],['B05',-1]])add(id,[r('a','Sechstel im ersten Bruch',0,6,5),r('b','Viertel im zweiten Bruch',0,4,1)],sign===1?'Warum müssen die Teile vor dem Zusammenlegen gleich groß werden?':'Welche Stückgröße bleibt beim Wegnehmen erhalten?','Die Zähler zählen gleiche Teile. Die gemeinsame Stückgröße ist hier ein Zwölftel.',v=>{let n=v.a*2+sign*v.b*3;return svg(bar(v.a*2,12,55,`${v.a}/6 = ${v.a*2}/12`)+bar(v.b*3,12,145,`${v.b}/4 = ${v.b*3}/12`,alt),'Beide Brüche sind in Zwölftel umgeteilt')+statement(`${v.a}/6 ${sign===1?'+':'−'} ${v.b}/4 = (${v.a*2} ${sign===1?'+':'−'} ${v.b*3})/12 = ${reduced(n,12)}`,n<0?'Der abzuziehende Anteil ist größer: Das Ergebnis ist negativ.':'Der Nenner wird nicht addiert oder subtrahiert.');},'Beim Erweitern bleiben beide Bruchwerte gleich.','Auch null, Ergebnisse über1 und negative Differenzen werden korrekt beschrieben.');
  add('B06',[r('a','Drittel von der Breite',0,3,2),r('b','Viertel von der Höhe',0,4,3)],'Wo liegt der Anteil vom Anteil?','Das ganze Rechteck ist 1. Blau markiert den gewählten Anteil der Breite, Braun den Anteil der Höhe. Die dunkle Überlappung gehört zu beiden.',v=>{let s='';for(let y=0;y<4;y++)for(let x=0;x<3;x++)s+=rect(120+x*120,45+y*45,120,45,x<v.a&&y<v.b?'#8baeba':x<v.a?tint:y<v.b?pale:'#fff');s+=ln(120,30,120+v.a*120,30,ink,4)+tx(300,12,v.a+'/3 der Breite',16,ink)+ln(105,45,105,45+v.b*45,alt,4)+tx(60,130,v.b+'/4',18,alt);return svg(s,'Bruchteile der Breite und Höhe mit dunkler gemeinsamer Fläche')+statement(v.a+'/3 · '+v.b+'/4 = '+v.a*v.b+'/12 = '+reduced(v.a*v.b,12),'Die '+v.a*v.b+' dunklen Felder von insgesamt 12 Feldern zeigen das Produkt.');},'Ein unverändertes Ganzes mit zwölf gleich großen Teilflächen.','Beide Anteile zwischen 0 und 1.');
  add('B07',[r('a','Vorrat in Viertellitern',1,8,3),r('b','Portionsgröße in Viertellitern',1,6,2)],'Wie viele Portionen passen in den Vorrat – auch als Teilportion?','Oben siehst du den Vorrat, darunter eine ganze Portion im selben Maßstab. Vergleiche ihre Längen.',v=>{const q=v.a/v.b;let s=bar(v.a,8,70,'Vorrat: '+v.a+'/4 Liter (Rahmen: 2 Liter)');for(let j=0;j<=Math.floor(q);j++)s+=ln(65+j*v.b*470/8,65,65+j*v.b*470/8,116,alt,3);s+=rect(65,170,v.b*470/8,38,pale,alt)+tx(300,147,'Eine ganze Portion: '+v.b+'/4 Liter',18,alt);return svg(s,'Vorrat und eine ganze Portion mit identischem Längenmaßstab')+statement(v.a+'/4 : '+v.b+'/4 = '+v.a+'/'+v.b+' '+(Number(q.toFixed(3))===q?'=':'≈')+' '+f(q)+' Portionen',Math.floor(q)+' volle Portionen'+(q%1?' und '+reduced(v.a%v.b,v.b)+' einer Portion.':'.'));},'Gezählt werden Portionen, nicht Liter.','Auch eine Portion größer als der Vorrat bleibt vollständig sichtbar.');
  add('B08',[r('part','Bekannter Anteil in cm',3,30,15,3)],'Wenn drei Viertel länger werden, wie verändert sich das Ganze?','Vom bekannten Anteil gehst du zuerst auf ein Teilstück zurück und dann auf alle Teilstücke.',v=>svg(bar(3,4,90,`3/4 des Bandes sind ${v.part} cm`,ink,300-v.part/3*22,v.part/3*44)+tx(300,185,`Ein Viertel: ${v.part} : 3 = ${v.part/3} cm`,20),'Vier gleiche Bandabschnitte mit festem Längenmaßstab, drei davon bekannt')+statement(`Ganzes = ${v.part} : 3 · 4 = ${v.part/3*4} cm`),'Vier gleich lange Teile bilden das Ganze.','Bekannter Anteil positiv; ganzzahlige Zentimeter für nachvollziehbare Rückrechnung.');

  add('D01',[r('hundredths','Hundertstel',0,100,58),r('tenths','Zehntel im Vergleich',0,10,6)],'Warum ist 0,6 dasselbe wie 0,60?','Beide Quadrate sind gleich große Ganze. Links sind es 100 kleine Felder, rechts 10 Streifen: Ein Streifen ist so groß wie 10 kleine Felder.',v=>svg(grid(10,10,(x,y)=>y*10+x<v.hundredths,200,200,60,40)+grid(10,1,x=>x<v.tenths,200,200,340,40)+tx(160,20,v.hundredths+' Hundertstel',17)+tx(440,20,v.tenths+' Zehntel',17),'Gleich große Quadrate in Hundertstel und Zehntel unterteilt',270)+statement(f(v.hundredths/100)+' '+(v.hundredths===v.tenths*10?'=':v.hundredths<v.tenths*10?'&lt;':'&gt;')+' '+f(v.tenths/10),v.tenths+' Zehntel = '+v.tenths*10+' Hundertstel.'),'Beide Ganzen haben dieselbe sichtbare Fläche.','Anteile von 0 bis 1.');
  add('D02',[r('a','Dividend in Zehnteln',1,60,24),r('b','Divisor in Zehnteln',1,12,6),r('shift','Beide Zahlen verzehnfachen',0,2,0)],'Warum darfst du bei einer Division beide Zahlen gleich weit verschieben?','Beide Zahlen mit demselben Faktor multiplizieren verändert die Anzahl der Portionen nicht.',v=>{let k=10**v.shift;return table(['Dividend','Divisor','Quotient (ggf. gerundet)'],[[f(v.a/10),f(v.b/10),f(v.a/v.b)],[f(v.a/10*k),f(v.b/10*k),f(v.a/v.b)]])+numberLine([[0,'0'],[v.a/10,f(v.a/10)]],0,Math.max(v.a,v.b)/10,[[0,v.b/10,'eine Portion',alt]],{step:Math.max(.1,PlotScale.step(0,Math.max(v.a,v.b)/10,12)),minor:.1})+statement(`${f(v.a/10*k)} : ${f(v.b/10*k)} ${Number((v.a/v.b).toFixed(3))===v.a/v.b?"=":"≈"} ${f(v.a/v.b)}`);},'Der Quotient bleibt bei gemeinsamer Skalierung gleich.','Divisor strikt positiv. Wiederkehrende Dezimalwerte mit Näherung dargestellt.');
  add('D03',[r('n','Zähler',1,9,1),r('d','Nenner',2,12,3),r('digits','Divisionsschritte',1,10,6)],'Woran erkennst du eine endliche oder periodische Dezimalzahl?','Sobald derselbe Rest wiederkommt, wiederholt sich die weitere Division.',v=>{let rest=v.n%v.d,seen={},rows=[],digits=[],repeat=-1;for(let i=0;i<v.digits;i++){if(rest===0)break;if(seen[rest]!==undefined){repeat=seen[rest];break;}seen[rest]=i;let before=rest*10,z=Math.floor(before/v.d);rest=before%v.d;digits.push(z);rows.push([i+1,`${before} : ${v.d}`,z,rest]);}let d=digits.join(''),num=Math.floor(v.n/v.d)+','+(repeat>=0?d.slice(0,repeat)+'<span style="text-decoration:overline">'+d.slice(repeat)+'</span>':d||'0');return statement(`${v.n}/${v.d} ${rest===0||repeat>=0?'=':'≈'} ${num}${rest!==0&&repeat<0?'…':''}`,rest===0?'Rest0: Die Darstellung endet.':repeat>=0?'Ein bereits bekannter Rest ist wieder da: Die markierte Ziffernfolge wiederholt sich.':'Noch nicht fertig. Erhöhe die Anzahl der Schritte.')+table(['Schritt','Division','Ziffer','Rest'],rows);},'Die Division folgt beim gleichen Rest denselben nächsten Schritten.','Nenner2–12; endliche, rein- und gemischtperiodische Beispiele; keine Rundungsbehauptung für abgeschnittene Ziffern.');
  add('R01',[r('x','Zahl',-8,8,-5)],'Wo liegt die Gegenzahl? Was bleibt beim Vorzeichenwechsel gleich?','Die Gegenzahl liegt spiegelbildlich zu0. Ihr Betrag, also der Abstand zu0, ist gleich.',v=>numberLine([[v.x,`Zahl ${v.x}`],[-v.x,`Gegenzahl ${-v.x}`,alt]],-10,10)+statement(`|${v.x}| = ${Math.abs(v.x)}`,`${v.x<0?'Die negative Zahl liegt links von0.':v.x>0?'Die positive Zahl liegt rechts von0.':'Null ist ihre eigene Gegenzahl.'}`),'Gegenzahlen haben denselben Abstand vom Ursprung.','Null wird separat beschrieben; gleiche Punkte dürfen zusammenfallen.');
  add('R02',[r('a','Startzahl',-6,6,-2),r('b','Zweite Zahl',-6,6,-4),opt('op','Rechenzeichen',[['+','Addieren'],['−','Subtrahieren']])],'In welche Richtung geht der zweite Pfeil bei minus einer negativen Zahl?','Subtrahieren heißt die Gegenzahl addieren. Die Richtung wird so eindeutig.',v=>{let d=v.op==='+'?v.b:-v.b;return numberLine([[v.a,`Start ${v.a}`],[v.a+d,`Ziel ${v.a+d}`,alt]],-12,12,[[0,v.a,'Startwert'],[v.a,v.a+d,`${d>=0?'+':''}${d}`,alt]])+statement(`${v.a} ${v.op} (${v.b}) = ${v.a} + (${d}) = ${v.a+d}`);},'Der zweite Pfeil zeigt immer die tatsächlich addierte Änderung.','Negative Summanden geklammert; Ergebnisbereich−12 bis12.');
  add('R03',[r('b','Zweiter Faktor',-4,4,-2)],'Setze die Zahlenfolge fort: Warum ergibt negativ mal negativ einen positiven Wert?','Wenn der zweite Faktor jeweils um1 sinkt, steigt das Produkt mit−3 jeweils um3.',v=>table(['Zweiter Faktor b','Produkt −3 · b','Änderung zur nächsten Zeile'],Array.from({length:9},(_,i)=>4-i).map(b=>[b,`<strong ${b===v.b?'style="background:#dce8ed;padding:5px"':''}>${-3*b}</strong>`,b>-4?'+3':'']))+numberLine([[-3*v.b,`−3 · (${v.b}) = ${-3*v.b}`]],-12,12),'Das Distributivgesetz verlangt konstanten Zuwachs in der Produktfolge.','Null als Übergang; keine unzutreffende Regel aus wiederholter Addition negativer Häufigkeiten.');
  add('R04',[r('a','Betrag der Basis',1,5,3),r('n','Exponent',2,5,2)],'Wann liefert eine Klammer um die negative Basis ein anderes Ergebnis?','In (−a)ⁿ gehört das Minus zu jedem Faktor; bei −aⁿ steht es außerhalb der Potenz.',v=>table(['Ausdruck','Als Produkt','Wert'],[[`(−${v.a})<sup>${v.n}</sup>`,Array(v.n).fill(`(−${v.a})`).join(' · '),(-v.a)**v.n],[`−${v.a}<sup>${v.n}</sup>`,'−('+Array(v.n).fill(v.a).join(' · ')+')',-(v.a**v.n)]])+statement(v.n%2?'Bei ungeradem Exponenten stimmen die Werte überein.':'Bei geradem Exponenten sind die Werte Gegenzahlen.'),'Die Position der Klammer entscheidet, wie oft das Minus als Faktor vorkommt.','Basisbetrag positiv, Exponenten2–5; gerade und ungerade Fälle sichtbar.');
  add('R05',[r('start','Temperatur am Anfang in °C',-10,10,-3),r('change','Temperaturänderung in °C',-10,10,8)],'Wie kann die Temperatur steigen und trotzdem negativ bleiben?','Ein Wert und seine Änderung sind verschieden. Der Pfeil beschreibt die Änderung.',v=>numberLine([[v.start,`Anfang ${v.start} °C`],[v.start+v.change,`Ende ${v.start+v.change} °C`,alt]],-20,20,[[v.start,v.start+v.change,`${v.change>0?'+':''}${v.change} °C`,alt]])+statement(`${v.start} °C + (${v.change} °C) = ${v.start+v.change} °C`),'Der Endwert ist Anfang plus Änderung.','Fallende, steigende und unveränderte Temperaturen; Vorzeichen des Endwerts unabhängig von Änderungsrichtung.');
  add('P01',[r('p','Prozent',0,200,35,5)],'Was bedeuten mehr als100 Prozent im Bild?','Ein ganzes Hundertfeld ist100%. Die verschiedenen Schreibweisen meinen denselben Anteil.',v=>{let s=grid(10,10,(x,y)=>y*10+x<v.p,200,200,60,30);if(v.p>100)s+=grid(10,10,(x,y)=>y*10+x<v.p-100,200,200,340,30);return svg(s,'Hundertfelder für den Prozentanteil')+statement(`${v.p}% = ${v.p}/100 = ${reduced(v.p,100)} = ${f(v.p/100)}`);},'100% beziehen sich immer auf ein Ganzes.','Prozentanteile0–200 einschließlich mehr als einem Ganzen.');
  add('P02',[r('g','Grundwert G',20,200,60,10),r('p','Prozentsatz in Prozent',0,100,20,5)],'Wenn das Ganze doppelt so groß ist, was passiert bei gleichem Prozentsatz?','Grundwert und Prozentsatz legen den Prozentwert gemeinsam fest.',v=>svg(bar(v.p,100,90,`Ganzes G = ${v.g}`)+tx(300,175,`Anteil W = ${f(v.g*v.p/100)}`,22),'Prozentstreifen mit variablem Bezugswert')+statement(`W = ${v.g} · ${f(v.p/100)} = ${f(v.g*v.p/100)}`,`Hier ist p = ${f(v.p/100)} der Dezimalanteil; ${v.p}% ist die Prozentangabe.`),'Bei gleichem p bleibt W/G konstant; bei gleichem G verändert p die Anteilslänge.','Grundwert positiv,0% zulässig; keine Rückrechnung durch p=0.');
  add('P03',[r('p','Rabatt in Prozent',0,80,20,5),r('second','Anschließende Erhöhung in Prozent',0,80,20,5)],'Macht eine Erhöhung um denselben Prozentsatz den Rabatt rückgängig?','Die zweite Änderung bezieht sich auf den neuen, kleineren Preis.',v=>{let discounted=80*(1-v.p/100),end=discounted*(1+v.second/100),scale=3;return svg(rect(75,45,80*scale,38)+tx(330,64,'80 €',18,ink,'start')+rect(75,115,discounted*scale,38)+tx(75+discounted*scale+12,134,`${f(discounted)} €`,18,ink,'start')+rect(75,185,end*scale,38,pale,alt)+tx(75+end*scale+12,204,`${f(end)} €`,18,alt,'start'),'Drei Preise mit gleicher Längenskala')+statement(`80 · ${f(1-v.p/100)} · ${f(1+v.second/100)} = ${f(end)} €`);},'Jeder Faktor wirkt auf den unmittelbar vorherigen Wert.','Rabatt unter100%; keine negativen Preise; Skala für alle Balken identisch.');
  add('P04',[r('k','Kapital in Euro',100,1000,400,100),r('p','Jahreszins in Prozent',0,10,3,0.5)],'Was passiert bei gleichem Zinssatz mit den Zinsen, wenn das Kapital steigt?','Blau zeigt das Kapital, Braun die zusätzlichen Zinsen für ein volles Jahr. Beide Balkenteile verwenden denselben festen Maßstab.',v=>{const z=v.k*v.p/100;return svg(rect(70,70,v.k*.4,60)+rect(70+v.k*.4,70,z*.4,60,pale,alt)+tx(300,35,f(v.k)+' € Kapital',20,ink)+tx(300,175,f(z)+' € Zinsen nach einem Jahr',20,alt),'Kapital und Jahreszinsen als Längen im festen Maßstab')+statement('Z = '+v.k+' · '+f(v.p/100)+' = '+f(z)+' €','Nach einem Jahr: '+f(v.k+z)+' €. Hier ohne Gebühren und ohne Zinseszins.');},'Kapital und Zinsen wachsen bei festem Zinssatz im selben Verhältnis.','Ein Jahr, ohne Zinseszins.');

  D.T01={preserveExisting:true,question:'Wie wird aus der eingesetzten Zahl Schritt für Schritt ein Ergebnis?',explanation:'Die bestätigte vertikale Einsetz- und Rechenkette mit zwei Beispielen bleibt erhalten.',controls:[]};
  add('T02',[r('a','Anzahl der ersten x-Terme',1,5,3),r('b','Weitere x-Terme',1,4,2),r('c','Anzahl der y-Terme',1,4,2)],'Welche Bausteine darfst du gemeinsam zählen?','Gleichartige Terme haben denselben Variablenteil. x- und y-Terme bleiben getrennt.',v=>{let s='';for(let i=0;i<v.a+v.b;i++)s+=rect(40+i*50,45,42,70)+tx(61+i*50,80,'x');for(let i=0;i<v.c;i++)s+=rect(40+i*70,160,62,45,pale,alt)+tx(71+i*70,182,'y',16,alt);return svg(s,'Gleichartige x- und y-Bausteine')+statement(`${v.a}x + ${v.b}x + ${v.c}y = ${v.a+v.b}x + ${v.c}y`,'Die gezeichnete Größe ist ein Symbol für die Art des Terms, kein festgelegter Wert von x oder y.');},'Nur die Anzahl gleichartiger Bausteine wird zusammengefasst.','Positive Koeffizienten; keine Behauptung x=y aus zufälligem Zahlenwert.');
  add('T03',[r('a','Äußerer Faktor',-4,4,3),r('b','Zahl in der Klammer',1,6,2)],'Wie viele Summanden muss der äußere Faktor erreichen?','Der äußere Faktor wirkt auf jeden Summanden der Klammer, auch mit negativem Vorzeichen.',v=>svg(tx(300,50,`${v.a} · (x + ${v.b})`,26)+ln(250,78,165,155)+ln(350,78,435,155)+rect(90,165,150,55)+tx(165,192,`${v.a}x`,23)+rect(360,165,150,55,pale,alt)+tx(435,192,`${v.a*v.b}`,23,alt),'Zwei Verbindungen vom äußeren Faktor zu beiden Summanden')+statement(`${v.a}(x + ${v.b}) = ${v.a}x ${v.a*v.b<0?'−':'+'} ${Math.abs(v.a*v.b)}`),'Jeder Summand erhält denselben äußeren Faktor.','Faktor−4 bis4 schließt−1 und0 ein; Darstellung keine negative geometrische Länge.');
  add('T04',[r('a','Gemeinsame Höhe',1,6,4),r('b','Breite des zweiten Teils',1,6,3)],'Welche Seite teilen beide Teilflächen?','Ausklammern liest dieselbe Fläche als Produkt statt als Summe.',v=>svg(rect(75,55,210,v.a*24)+rect(285,55,v.b*24,v.a*24,pale,alt)+tx(180,37,'x')+tx(285+v.b*12,37,v.b)+tx(48,55+v.a*12,v.a)+tx(180,55+v.a*12,`${v.a}x`)+tx(285+v.b*12,55+v.a*12,v.a*v.b),'Zwei Rechtecke mit gemeinsamer Höhe')+statement(`${v.a}x + ${v.a*v.b} = ${v.a}(x + ${v.b})`,'Das Flächenbild zeigt positive Längen. Die algebraische Gleichheit gilt auch für andere x-Werte.'),'Gesamtfläche gleich; die gemeinsame Höhe wird zum Faktor.','Geometrisches Modell setzt x>0 voraus, Identität gilt allgemein.');
  add('T05',[r('a','a in (x + a)',1,5,2),r('b','b in (x + b)',1,5,3)],'Wo entstehen die vier Teilprodukte?', 'Jeder Summand einer Klammer trifft jeden Summanden der anderen Klammer.',v=>{let x=135,a=v.a*25,b=v.b*25;return svg(tx(100+x/2,18,'x')+tx(100+x+a/2,18,v.a)+tx(78,40+x/2,'x')+tx(78,40+x+b/2,v.b)+rect(100,40,x,x)+rect(100+x,40,a,x,pale,alt)+rect(100,40+x,x,b,pale,alt)+rect(100+x,40+x,a,b)+tx(100+x/2,40+x/2,'x²',22)+tx(100+x+a/2,40+x/2,`${v.a}x`,19)+tx(100+x/2,40+x+b/2,`${v.b}x`,19)+tx(100+x+a/2,40+x+b/2,v.a*v.b,18), 'Rechteck aus vier Teilprodukten',310)+statement(`(x + ${v.a})(x + ${v.b}) = x² + ${v.a}x + ${v.b}x + ${v.a*v.b} = x² + ${v.a+v.b}x + ${v.a*v.b}`);},'Vier Teilflächen ergeben dieselbe Gesamtfläche wie das Produkt der Seitenlängen.','x als positive Modelllänge; Identität unabhängig vom konkreten x.');
  add('T06',[r('a','Quadratseite a',2,7,5),r('b','Zusätzliche Länge b',1,5,2)],'Warum sind zwei gemischte Rechtecke nötig?','Das Quadrat von a+b enthält a², b² und zwei Rechtecke mit der Fläche ab.',v=>{let u=24,a=v.a*u,b=v.b*u;return svg(tx(180+a/2,8,'a')+tx(180+a+b/2,8,'b')+tx(160,20+a/2,'a')+tx(160,20+a+b/2,'b')+rect(180,20,a,a)+rect(180+a,20,b,a,pale,alt)+rect(180,20+a,a,b,pale,alt)+rect(180+a,20+a,b,b)+tx(180+a/2,20+a/2,'a²',22)+tx(180+a+b/2,20+a/2,'ab',19)+tx(180+a/2,20+a+b/2,'ab',19)+tx(180+a+b/2,20+a+b/2,'b²',16),'Vier Teile eines Quadrats',335)+statement(`(${v.a} + ${v.b})² = ${v.a*v.a} + 2 · ${v.a*v.b} + ${v.b*v.b} = ${(v.a+v.b)**2}`);},'Alle vier Teile bedecken genau das große Quadrat.','Positive Seiten; verändert wird b, nicht nur eine Zahl in einer Formel.');
  add('T07',[r('x','Kurze Rechteckseite x in cm',1,7,3),r('a','Zusätzliche Länge in cm',1,4,2)],'Wie beschreiben zwei verschiedene Terme denselben Rand?','Die lange Seite ist x+a. Beim Umfang kommen beide Seiten je zweimal vor.',v=>{let a=v.x*23,b=(v.x+v.a)*23;return svg(rect(100,45,b,a,'#fff')+tx(100+b/2,25,`${v.x+v.a} cm = x + ${v.a}`)+tx(100+b/2,70+a,'x + '+v.a)+tx(75,45+a/2,`x`)+tx(125+b,45+a/2,'x'),'Rechteckseiten als Situation für einen Term')+statement(`U = 2x + 2(x + ${v.a}) = 4x + ${2*v.a}`,`Für x = ${v.x}: U = ${4*v.x+2*v.a} cm.`);},'Die vier Randseiten ergeben denselben Umfang in beiden Termformen.','Seitenlängen positiv; variable Bedeutung und Einheit ausdrücklich benannt.');

  function balance(left,right,labelL,labelR){let d=Math.max(-18,Math.min(18,(right-left)*3));return svg(poly([[265,220],[335,220],[300,120]],'#e8ecee','#87979f')+ln(90,115-d,510,115+d,ink,4)+ln(140,115-d,140,170-d)+ln(460,115+d,460,170+d)+rect(65,170-d,150,35)+rect(385,170+d,150,35,pale,alt)+tx(140,65-d,labelL,20)+tx(460,65+d,labelR,20)+tx(300,30,left===right?'Gleichgewicht':'Kein Gleichgewicht',19),`${labelL} und ${labelR}: ${left===right?'gleich':'ungleich'}`);}
  add('E01',[r('x','Wert für x ausprobieren',0,8,3)],'Für welchen Wert ist die Aussage 2x+3=11 wahr?','Eine Gleichung ist eine Bedingung. Nur passende eingesetzte Werte sind Lösungen.',v=>balance(2*v.x+3,11,`2 · ${v.x} + 3 = ${2*v.x+3}`,'11')+statement(`${2*v.x+3} ${2*v.x+3===11?'=':'≠'} 11`,2*v.x+3===11?`x = ${v.x} ist eine Lösung.`:`x = ${v.x} ist keine Lösung.`),'Die rechte Seite bleibt11, links wird der Term ausgewertet.','Kleine nichtnegative x-Werte; Waage zeigt Zahlenwerte und ist kein Beweis für alle Gleichungen.');
  add('E02',[r('step','Umformungsschritt',0,2,0)],'Was passiert, wenn beide Seiten denselben Schritt bekommen?','Erst3 abziehen, dann durch2 teilen: Die Lösungsmenge bleibt gleich.',v=>{let labels=[['2x + 3','11'],['2x','8'],['x','4']][v.step];return balance([11,8,4][v.step],[11,8,4][v.step],labels[0],labels[1])+table(['Gleichung','Auf beiden Seiten'],[['2x + 3 = 11',v.step>=1?'−3':''],...(v.step>=1?[['2x = 8',v.step>=2?':2':'']]:[]),...(v.step>=2?[['x = 4','Probe: 2 · 4 + 3 = 11']]:[])]);},'Beidseitige umkehrbare Operationen erhalten die Lösungx=4.','Multiplikation/Division hier mit2≠0; Schritte können rückwärts erkundet werden.');
  add('E03',[r('step','Nenner beseitigen und lösen',0,3,0)],'Warum muss auch die ganze Zahl2 mit6 multipliziert werden?','Ein gemeinsamer Nenner beseitigt die Brüche nur, wenn wirklich jeder Summand mitmultipliziert wird.',v=>{let rows=[['x/2 + x/3 = 2','beide Seiten ·6'],['3x + 2x = 12','zusammenfassen'],['5x = 12','beide Seiten :5'],['x = 12/5 = 2,4','Probe: 1,2 + 0,8 = 2']];return table(['Gleichung','Schritt'],rows.slice(0,v.step+1))+svg(tx(120,55,'x/2',25)+tx(300,55,'x/3',25)+tx(480,55,'2',25)+[120,300,480].map(x=>ln(x,80,x,155)+tx(x+24,120,'·6',17)).join('')+tx(120,195,'3x',25)+tx(300,195,'2x',25)+tx(480,195,'12',25),'Multiplikation mit6 erreicht alle drei Terme');},'Der Faktor6 wirkt auf jeden Summanden beider Seiten.','Nur bekannte Nenner2 und3; kein unzulässiges Streichen innerhalb einer Summe.');
  add('E04',[r('u','Fester Umfang U in cm',12,28,20,2),r('a','Seite a in cm',1,12,6)],'Wie muss b reagieren, damit der Umfang gleich bleibt?','Die Umfangsformel lässt sich nach b umstellen: b=U/2−a.',v=>{let b=v.u/2-v.a;if(b<=0)return statement(`b = ${v.u}/2 − ${v.a} = ${b} cm`,'Damit entsteht kein Rechteck mit positiven Seiten. Wähle a kleiner als U/2.');let unit=16;return svg(rect(110,35,v.a*unit,b*unit)+tx(110+v.a*unit/2,20,`a = ${v.a} cm`)+tx(120+v.a*unit,35+b*unit/2,`b = ${b} cm`,17,ink,'start'),'Rechteck mit konstantem Umfang')+statement(`U = 2a + 2b ⇒ b = U/2 − a = ${b} cm`);},'Bei festem Umfang bleibta+b gleich.','Kein Rechteck bei b≤0, mit verständlicher Definitionsbereichsmeldung.');
  add('E05',[r('price','Preis pro Heft in Euro',1,6,3)],'Welcher Heftpreis passt gleichzeitig zur Einkaufssituation und zur Gleichung?','Zwei gleich teure Hefte und ein Stift für1€ kosten insgesamt7€.',v=>svg(rect(80,60,95,120)+tx(127,115,`${v.price} €`,23)+rect(210,60,95,120)+tx(257,115,`${v.price} €`,23)+rect(380,75,20,95,pale,alt)+tx(449,120,'1 €',22,alt),'Zwei gleiche Hefte und ein Stift')+statement(`2 · ${v.price} + 1 = ${2*v.price+1} €`,2*v.price+1===7?'Passt: Ein Heft kostet3€.':`Gesucht sind7€. ${2*v.price+1>7?'Der angenommene Heftpreis ist zu hoch.':'Der angenommene Heftpreis ist zu niedrig.'}`),'Beide Hefte haben denselben unbekannten Preis.','Einfache positive Europreise; Lösung und Situation verbunden.');
  add('E06',[r('x','x-Koordinate des Prüfpunktes',-2,5,1)],'Bei welchem x liegen die Punkte beider Geraden genau übereinander?','Ein Schnittpunkt erfüllt beide Gleichungen gleichzeitig.',v=>graph([{fn:x=>2*x},{fn:x=>-x+3}],[[v.x,2*v.x,'I'],[v.x,-v.x+3,'II',alt]],[-3,6,-4,10])+statement(`I: y = 2x → ${2*v.x}<br>II: y = −x + 3 → ${-v.x+3}`,2*v.x===-v.x+3?`Gemeinsamer Punkt S(${v.x}|${2*v.x}).`:'Gleiche x-Koordinate, verschiedene y-Werte: kein gemeinsamer Punkt.'),'Ein gemeinsamer Punkt benötigt in beiden Gleichungen dasselbe x und dasselbe y.','Beide Geraden haben verschiedene Steigungen; Schnittpunkt sichtbar.');
  add('E07',[r('c','Summe x + y',2,10,6)],'Wie verändert sich die Lösung, wenn die Summe wächst, aber y=2x bleibt?','Weil y=2x gilt, darfst du y in der anderen Gleichung durch2x ersetzen.',v=>{let x=v.c/3;return graph([{fn:x=>2*x},{fn:x=>v.c-x}],[[x,2*x,`S(${f(x)}|${f(2*x)})`]],[-1,5,-1,10])+table(['Einsetzen','Ergebnis'],[[`x + y = ${v.c}, y = 2x`,`x + 2x = ${v.c}`],[`3x = ${v.c}`,`x = ${reduced(v.c,3)}, y = ${reduced(2*v.c,3)}`]]);},'y bleibt doppelt so groß wiex; die zweite Bedingung legt den Schnittpunkt fest.','Lösungen als exakte Brüche; graphische Koordinatenbeschriftung gegebenenfalls gerundet.');
  add('E08',[opt('case','Geraden vergleichen',[['one','Ein Schnittpunkt'],['none','Parallel'],['all','Identisch']])],'Was unterscheidet keinen, einen und unendlich viele gemeinsame Punkte?','Entscheidend sind Steigung und Achsenabschnitt beider Geraden.',v=>{let m=v.case==='one'?-1:1,b=v.case==='all'?1:3;return graph([{fn:x=>x+1},{fn:x=>m*x+b,dash:v.case==='all'}],v.case==='one'?[[1,2,'S(1|2)']]:[],[-4,5,-3,6])+statement(`I: y = x + 1 · II: y = ${m===1?'x':'−x'} + ${b}`,v.case==='one'?'Verschiedene Steigungen: genau eine Lösung.':v.case==='none'?'Gleiche Steigung, andere Höhe: keine Lösung.':'Beide Gleichungen beschreiben dieselbe Gerade: unendlich viele Lösungen.');},'Die erste Gerade bleibt unverändert; zweite Steigung/Abschnitt bestimmen den Lösungstyp.','Identische Geraden als überlagerte gestrichelte Linie; keine falsche Anzahl durch Bildüberdeckung.');
  add('F00',[r('x','Anzahl der Hefte',0,6,3)],'Welche Eingaben passen zu einer Bestellung von ganzen Heften?','Eingabe und Ausgabe hängen über eine Regel zusammen. Hier kostet jedes Heft2€, dazu kommt1€ Verpackung.',v=>graph([],Array.from({length:7},(_,x)=>[x,2*x+1,x===v.x?`(${x}|${2*x+1})`:'',x===v.x?alt:ink]),[-1,7,-1,15],'',{xLabel:'Anzahl der Hefte x',yLabel:'Preis y in €'})+statement(`Preis(${v.x}) = 2 · ${v.x} + 1 = ${2*v.x+1} €`,'Die Punkte sind einzeln: Halbe Hefte werden in diesem Modell nicht bestellt. Der Grundpreis gilt auch für x=0 als rechnerischen Modellwert; eine echte Bestellung benötigt mindestens ein Heft.'),'Jede erlaubte Eingabe hat genau eine Ausgabe.','Diskrete Anzahl; rechnerischer Nullwert von tatsächlicher Bestellung getrennt.');
  add('F01',[r('k','Preis je kg in Euro',1,5,2),r('x','Masse in kg',0,5,3,0.5)],'Was bleibt gleich, wenn du die Masse verdoppelst?','Bei einem festen Kilopreis ist der Preis proportional zur Masse.',v=>graph([{fn:x=>x>=0?v.k*x:NaN}],[[v.x,v.k*v.x,`(${f(v.x)}|${f(v.k*v.x)})`]],[-0.5,5.5,-1,28],'',{xLabel:'Masse x in kg',yLabel:'Preis y in €'})+statement(`y = ${v.k}x`,v.x?`${f(v.k*v.x)} : ${f(v.x)} = ${v.k} €/kg`:'Der Graph geht durch(0|0). Den Quotienten 0/0 berechnen wir nicht.'),'Der Quotient y/x bleibt bei festem k fürx≠0 gleich.','x=0 als Ursprung gezeigt ohne Division durch null.');
  add('F02',[r('m','Steigung m',-3,3,2,0.5),r('b','Achsenabschnitt b',-3,3,1)],'Was verändert m, was verändert b?','b legt die Höhe bei x=0 fest. m ist die Änderung nach einem Schritt nach rechts.',v=>graph([{fn:x=>v.m*x+v.b}],[[0,v.b,`b=${v.b}`],[1,v.m+v.b,'']],[-4,4,-6,6],(X,Y)=>ln(X(0),Y(v.b),X(1),Y(v.b),alt,3)+ln(X(1),Y(v.b),X(1),Y(v.b+v.m),alt,3)+tx(X(.5),Y(v.b)+15,'1',14,alt)+tx(X(1)+15,(Y(v.b)+Y(v.b+v.m))/2,f(v.m),14,alt),{xStep:1,yStep:1,xMinor:.5,yMinor:.5,height:264})+statement(`y = ${f(v.m)}x ${v.b<0?'−':'+'} ${Math.abs(v.b)}`),'Änderung von b verschiebt die Gerade parallel; m verändert die Richtung.','m=0, positive und negative Steigungen; Steigungsdreieck im Zeichenbereich.');
  add('F03',[r('m','Steigung',-2,2,1),r('b','Startwert',-2,2,2),r('x','Tabellenpunkt hervorheben',-2,2,1)],'Wo findest du denselben Wert in Term, Tabelle und Graph?','Jede Tabellenspalte liefert genau ein Koordinatenpaar für den Graphen.',v=>graph([{fn:x=>v.m*x+v.b}],[[v.x,v.m*v.x+v.b,`P(${v.x}|${v.m*v.x+v.b})`]],[-3,3,-7,7])+table(['x','−2','−1','0','1','2'],[['y',...[-2,-1,0,1,2].map(x=>x===v.x?`<strong style="color:${alt}">${v.m*x+v.b}</strong>`:v.m*x+v.b)]])+statement(`y = ${v.m}x ${v.b<0?'−':'+'} ${Math.abs(v.b)}`),'Term, Tabelle und Graph beschreiben dieselbe Zuordnung.','Ganzzahlige Punkte sichtbar, horizontale Gerade möglich.');
  add('F04',[r('x','x-Koordinate von B',-1,5,3),r('y','y-Koordinate von B',-2,8,7)],'Was passiert, wenn beide Punkte dieselbe x-Koordinate haben?','Die Steigung ist der Höhenunterschied geteilt durch den waagerechten Unterschied.',v=>{let dx=v.x-1,dy=v.y-3,m=dy/dx,b=3-m;return graph(dx?[{fn:x=>m*x+b}]:[],[[1,3,'A'],[v.x,v.y,'B',alt]],[-2,6,-3,9],(X,Y)=>(!dx&&dy?ln(X(1),Y(-3),X(1),Y(9),ink,3):'')+ln(X(1),Y(3),X(v.x),Y(3),alt,2)+ln(X(v.x),Y(3),X(v.x),Y(v.y),alt,2))+statement(dx?`m = (${v.y} − 3)/(${v.x} − 1) = ${reduced(dy,dx)}`:dy?'Keine Funktionsgerade y=mx+b.':'A und B sind derselbe Punkt.',dx?`b = 3 − m; näherungsweise: y = ${f(m)}x ${b<0?'−':'+'} ${f(Math.abs(b))}`:dy?'Eine senkrechte Gerade erlaubt für x=1 mehrere y-Werte.':'Ein einzelner Punkt legt die Steigung nicht fest.');},'Beide gegebenen Punkte müssen auf der gesuchten Geraden liegen.','Gleiche x-Koordinaten und identische Punkte werden getrennt behandelt.');
  add('F05',[r('m','Steigung m',-3,3,2),r('b','Achsenabschnitt b',-4,4,-2)],'Wo ist die Ausgabe gleich null? Ist die Stelle dasselbe wie der Punkt?','Eine Nullstelle ist ein x-Wert. Der zugehörige Punkt hat y=0.',v=>{let x=-v.b/v.m;return graph([{fn:x=>v.m*x+v.b}],v.m?[[x,0,'N']]:[],[-6,6,-6,6])+statement(v.m?`0 = ${v.m}x ${v.b<0?'−':'+'} ${Math.abs(v.b)} ⇒ x = ${reduced(-v.b,v.m)}`:v.b?'Keine Nullstelle.':'Jeder x-Wert ist eine Nullstelle.',v.m?`Punkt N(${f(x)}|0); nicht verwechseln mit der Stelle x≈${f(x)}.`:v.b?'Die waagerechte Gerade trifft die x-Achse nicht.':'Die Gerade ist die x-Achse.');},'An jedem Nullstellenpunkt ist y genau0.','m=0 samt b=0 wird abgefangen; mögliche Stelle außerhalb des Ausschnitts numerisch benannt.');
  add('F06',[r('x','Anzahl gleich starker Pumpen',1,8,3)],'Warum halbiert sich die Zeit bei doppelter Pumpenzahl?','Die gleiche Arbeit wird ideal auf gleich starke Pumpen verteilt. Sinnvoll sind nur ganze Pumpenzahlen; die Kurve dient zur Orientierung. Im Rechteck ist die Breite die Pumpenzahl und die Höhe die Arbeitszeit.',v=>graph([{fn:x=>x>0?12/x:NaN}],[[v.x,12/v.x,'']], [0,9,0,13],'',{xLabel:'Anzahl der Pumpen x',yLabel:'Arbeitszeit y in Stunden'})+svg(rect(100,40,v.x*35,12/v.x*12)+tx(100+v.x*35/2,25,v.x+' Pumpen',16)+tx(112+v.x*35,40+6/v.x*12,reduced(12,v.x)+' h',16,alt,'start')+tx(300,215,`${v.x} · (${reduced(12,v.x)}) = 12 Pumpenstunden`,20),'Rechteck mit konstantem Produkt',245)+statement(`${v.x} Pumpen brauchen ${reduced(12,v.x)} Stunden.`),'Das Produkt aus Pumpenzahl und Arbeitszeit bleibt12.','Mindestens eine Pumpe; gleiche Leistung, unveränderte Arbeit und ideale Verteilung genannt.');
  add('F07',[opt('kind','Zuordnung',[['prop','y = 2x'],['anti','y = 12/x'],['linear','y = 2x + 3']])],'Welche Prüfung passt: Quotient, Produkt oder gleicher Zuwachs?','Ein Muster in der Tabelle verrät die Zuordnungsart.',v=>{let fn=v.kind==='prop'?x=>2*x:v.kind==='anti'?x=>12/x:x=>2*x+3;return graph([{fn:x=>x>0?fn(x):NaN}],[],[0,7,0,16])+table(['x','y','y/x','x·y'],[1,2,3,4,6].map(x=>[x,f(fn(x)),f(fn(x)/x),f(x*fn(x))]))+statement(v.kind==='prop'?'Quotient konstant: proportional.':v.kind==='anti'?'Produkt konstant: antiproportional.':'Zuwachs konstant, Quotient nicht: linear, aber nicht proportional.');},'Die drei Zuordnungen unterscheiden sich durch verschiedene konstante Beziehungen.','Nur positive x für Vergleich mit12/x; keine Division durch null.');
  add('F08',[r('t','Zeit in Minuten',0,6,3,0.5)],'Was bedeutet der Teil der Geraden nach dem leeren Tank?','Ein lineares Modell gilt nur so lange, wie es zur Situation passt.',v=>graph([{fn:x=>x>=0&&x<=4?12-3*x:NaN},{fn:x=>x>4?12-3*x:NaN,color:'#9b9b9b',dash:true}],[[v.t,12-3*v.t,v.t<=4?'Tankinhalt':'rechnerischer Wert',v.t<=4?ink:alt]],[0,6,-7,14],'',{xLabel:'Zeit t in Minuten',yLabel:'Tankinhalt V in Litern'})+statement(`V(${f(v.t)}) = 12 − 3 · ${f(v.t)} = ${f(12-3*v.t)} Liter`,v.t<=4?'Für0≤t≤4 beschreibt die Formel das gleichmäßige Leeren.':'Negativer Tankinhalt ist unmöglich. Nach4 Minuten ist das Modell beendet; der Tank bleibt leer.'),'Die Abnahme ist im gültigen Zeitraum3 Liter je Minute.','Ungültiger Modellbereich wird gestrichelt und sprachlich markiert.');
  add('F09',[r('m','Steigung der Modellgeraden',1,3,2,0.1),r('b','Achsenabschnitt',-1,3,1,0.1)],'Muss eine gute Modellgerade jeden Messpunkt treffen?','Die Abstände zeigen, wie gut die Gerade den gesamten Trend beschreibt.',v=>{let pts=[[1,2.8],[2,5.3],[3,6.8],[4,9.2],[5,10.9]],ss=pts.reduce((s,p)=>s+(p[1]-(v.m*p[0]+v.b))**2,0);return graph([{fn:x=>v.m*x+v.b}],pts.map(p=>[...p,'']),[0,6,0,20],(X,Y)=>pts.map(([x,y])=>ln(X(x),Y(y),X(x),Y(v.m*x+v.b),alt,2)).join(''))+statement(`Summe der quadrierten Abstände ≈ ${f(ss)}`,'Versuche die Abstände insgesamt klein zu machen. Die Gerade beschreibt diese Messspanne näherungsweise; weit außerhalb ist eine Vorhersage unsicher.');},'Die Messpunkte bleiben fest; nur das Modell und seine Abweichungen verändern sich.','Keine perfekte Anpassung behauptet; Ausgabe gerundet, Extrapolation als unsicher benannt.');

  add('G01',[r('a','Rechteckbreite',2,7,5),r('b','Rechteckhöhe',2,7,3)],'Wann ist ein Rechteck auch ein Quadrat?','Die Winkelmarkierungen zeigen vier rechte Winkel. Vergleiche die beschrifteten Seitenlängen und mache sie gleich groß.',v=>{const x=150,y=35,w=v.a*30,h=v.b*30;let s=rect(x,y,w,h,'#fff')+tx(x+w/2,18,v.a)+tx(x-25,y+h/2,v.b);for(const[cx,cy,sx,sy]of[[x,y,1,1],[x+w,y,-1,1],[x,y+h,1,-1],[x+w,y+h,-1,-1]])s+=poly([[cx,cy],[cx+sx*10,cy],[cx+sx*10,cy+sy*10],[cx,cy+sy*10]],'none',alt);return svg(s,'Rechteck mit Seitenlängen und vier markierten rechten Winkeln',280)+statement(v.a===v.b?'Quadrat und Rechteck':'Rechteck',v.a===v.b?'Zusätzlich sind alle vier Seiten gleich lang.':'Alle vier Winkel sind recht. Noch sind nicht alle Seiten gleich lang.');},'Vier rechte Winkel bleiben, die Seitenlängen sind veränderbar.','Das Quadrat ist ein besonderes Rechteck.');
  add('G02',[r('angle','Winkel α in Grad',10,170,60)],'Was bleibt an einer geraden Linie für den Nebenwinkel übrig?','Die beiden farbigen Bögen markieren die Nebenwinkel α und β. Gemeinsam ergeben sie den gestreckten Winkel.',v=>{const a=v.angle*Math.PI/180,point=(r,t)=>[300+r*Math.cos(t),210-r*Math.sin(t)],A=point(50,a),B=point(65,a);return svg(ln(80,210,520,210)+ln(300,210,...point(160,a),alt,3)+'<path d="M350 210 A50 50 0 0 0 '+A.join(' ')+'" fill="none" stroke="'+alt+'" stroke-width="3"/><path d="M'+B.join(' ')+' A65 65 0 0 0 235 210" fill="none" stroke="'+ink+'" stroke-width="3"/>'+tx(...point(110,a/2),'α = '+v.angle+'°',18,alt)+tx(...point(110,(a+Math.PI)/2),'β = '+(180-v.angle)+'°',18,ink),'Zwei markierte Nebenwinkel an einer Geraden')+statement(v.angle+'° + '+(180-v.angle)+'° = 180°');},'Die Summe der Nebenwinkel bleibt 180°.','Bögen und Beschriftungen folgen beiden tatsächlichen Winkeln.');
  add('G03',[r('x','Erst waagerecht: x',-4,4,-2),r('y','Dann senkrecht: y',-4,4,3)],'Wie verändert nur x oder nur y den Punkt?','Die Reihenfolge ist immer x vor y: zuerst waagerecht, dann senkrecht.',v=>geometryGraph([],[[v.x,v.y,`P(${v.x}|${v.y})`]],[-5,5,-5,5],(X,Y)=>ln(X(0),Y(0),X(v.x),Y(0),ink,3)+ln(X(v.x),Y(0),X(v.x),Y(v.y),alt,3))+statement(`P(${v.x}|${v.y})`,`Vom Ursprung ${Math.abs(v.x)} nach ${v.x<0?'links':'rechts'}, dann ${Math.abs(v.y)} nach ${v.y<0?'unten':'oben'}.`),'Eine Koordinate ändert nur eine Bewegungsrichtung.','Alle Quadranten und Achsen; Nullwege zulässig.');
  add('G04',[opt('kind','Abbildung',[['mirror','Spiegelung an der y-Achse'],['shift','Verschiebung um (2|1)'],['rotate','Drehung um O(0|0): 90° gegen den Uhrzeigersinn']]),r('x','x des Punktes P',-3,3,2),r('y','y des Punktes P',-3,3,1)],'Wie bleibt die Form erhalten, obwohl ihre Lage wechselt?','Das kleine Dreieck bewegt sich mit dem Punkt. Längen und Winkel bleiben gleich.',v=>{let transform=([x,y])=>v.kind==='mirror'?[-x,y]:v.kind==='shift'?[x+2,y+1]:[-y,x],a=[[v.x,v.y],[v.x+1,v.y],[v.x,v.y+1]],b=a.map(transform),p=b[0];return geometryGraph([],[[...a[0],'P'],[...p,'P′',alt]],[-6,6,-6,6],(X,Y)=>(v.kind==='mirror'?ln(X(0),Y(-6),X(0),Y(6),alt,3,'5 4'):v.kind==='rotate'?dot(X(0),Y(0),alt)+tx(X(0)-12,Y(0)+18,'O',15,alt)+ln(X(0),Y(0),X(a[0][0]),Y(a[0][1]),alt,1,'4 4')+ln(X(0),Y(0),X(p[0]),Y(p[1]),alt,1,'4 4'):ln(X(a[0][0]),Y(a[0][1]),X(p[0]),Y(p[1]),alt,2,'4 4'))+poly(a.map(([x,y])=>[X(x),Y(y)]),tint,ink)+poly(b.map(([x,y])=>[X(x),Y(y)]),pale,alt))+statement(`P(${v.x}|${v.y}) → P′(${p[0]}|${p[1]})`);},'Seitenlängen und Winkel des Dreiecks bleiben erhalten.','Drehzentrum Ursprung und Drehrichtung explizit; Spiegelung an y-Achse.');
  add('G05',[opt('kind','Ortslinie',[['circle','Fester Abstand vom Mittelpunkt'],['bisector','Gleicher Abstand von A und B']]),r('t','Punkt auf der Ortslinie bewegen',0,100,30)],'Was bleibt bei allen Positionen des Punktes gleich?','Eine Ortslinie sammelt genau die Punkte, die die Bedingung erfüllen.',v=>{let c=v.kind==='circle',a=v.t/100*2*Math.PI,p=c?[3*Math.cos(a),3*Math.sin(a)]:[0,-4+v.t*.08],dist=Math.hypot(p[0]+2,p[1]);return geometryGraph([],c?[[0,0,'M'],[...p,'P']]:[[-2,0,'A'],[2,0,'B'],[...p,'P']],[-5,5,-5,5],(X,Y)=>c?`<ellipse cx="${X(0)}" cy="${Y(0)}" rx="${X(3)-X(0)}" ry="${Y(0)-Y(3)}" fill="none" stroke="${ink}"/>`+ln(X(0),Y(0),X(p[0]),Y(p[1]),alt,3):ln(X(-2),Y(0),X(2),Y(0),'#89979e')+dot(X(0),Y(0),alt,3)+tx(X(0)+15,Y(0)+18,'M',15,alt)+poly([[X(0),Y(0)],[X(0)+9,Y(0)],[X(0)+9,Y(0)-9],[X(0),Y(0)-9]],'none',alt)+ln(X(0),Y(-5),X(0),Y(5))+ln(X(-2),Y(0),X(p[0]),Y(p[1]),alt)+ln(X(2),Y(0),X(p[0]),Y(p[1]),alt))+statement(c?'Abstand MP = 3':`PA = PB ≈ ${f(dist)}`,c?'Die Position ändert sich, der Radius bleibt gleich.':'Die Mittelsenkrechte steht senkrecht auf AB und geht durch dessen Mittelpunkt.');},'Kreis: Abstand zum Zentrum; Mittelsenkrechte: gleiche Abstände zu den Endpunkten.','Kreis und Geraden verwenden dieselbe Skala in beiden Richtungen; Radius und Abstände geometrisch korrekt.');
  add('G06',[r('a','Abstand AC in cm',1,7,4),r('b','Abstand BC in cm',1,7,5)],'Wann entsteht aus zwei Kreisschnittpunkten ein Dreieck?','A und B liegen 6 cm auseinander. Der blaue Kreis enthält alle Punkte im gewählten Abstand von A; der braune Kreis die Punkte im Abstand von B.',v=>{const x=(v.a*v.a-v.b*v.b+36)/12,h2=v.a*v.a-x*x,valid=v.a+v.b>6&&Math.abs(v.a-v.b)<6,h=valid?Math.sqrt(h2):0,X=x=>234+x*22,Y=y=>205-y*22;let s=circle(X(0),Y(0),v.a*22,ink)+circle(X(6),Y(0),v.b*22,alt)+ln(X(0),Y(0),X(6),Y(0))+dot(X(0),Y(0),ink)+dot(X(6),Y(0),alt)+tx(X(0)-15,Y(0)+20,'A',18,ink)+tx(X(6)+15,Y(0)+20,'B',18,alt)+tx(X(3),Y(0)+20,'6 cm');if(valid)s+=poly([[X(0),Y(0)],[X(6),Y(0)],[X(x),Y(h)]],'#dce8ed44')+dot(X(x),Y(h))+tx(X(x),Y(h)-15,'C')+dot(X(x),Y(-h),alt)+tx(X(x),Y(-h)+18,'C′',16,alt);else if(Math.abs(h2)<1e-8)s+=dot(X(x),Y(0))+tx(X(x),Y(0)-18,'Berührpunkt',16);return svg(s,'Zwei vollständige Abstandskreise um A und B',395)+statement(valid?'Zwei Schnittpunkte – zwei spiegelbildliche Dreiecke.':Math.abs(h2)<1e-8?'Die Kreise berühren sich: kein echtes Dreieck.':'Die Kreise schneiden sich nicht: kein Dreieck.',valid?'C liegt auf beiden Kreisen. Deshalb passen beide Seitenlängen gleichzeitig.':'Für ein Dreieck muss gelten: |'+v.a+' − '+v.b+'| < 6 < '+v.a+' + '+v.b+'.');},'Jeder Schnittpunkt erfüllt gleichzeitig beide Abstandsbedingungen.','Volle Kreise; Berührung und disjunkte Kreise getrennt.');
  add('G07',[r('x','Spitze C seitlich bewegen: x-Koordinate',-1,7,2,0.5),opt('line','Besondere Linie',[['height','Höhe'],['median','Seitenhalbierende'],['bisector','Winkelhalbierende'],['perpendicular','Mittelsenkrechte']])],'Wann fallen die verschiedenen Linien zusammen?','Wähle eine Linie und verschiebe C. Die Markierungen zeigen ihren Auftrag: einen rechten Winkel, zwei gleiche Strecken oder zwei gleiche Winkel.',v=>{const A=[0,0],B=[6,0],C=[v.x,4],ca=Math.hypot(v.x,4),cb=Math.hypot(6-v.x,4),foot=v.line==='height'?v.x:v.line==='median'||v.line==='perpendicular'?3:6*ca/(ca+cb);return geometryGraph([],[[...A,'A'],[...B,'B'],[...C,'C'],[foot,0,'F',alt]],[-2,8,-1,6],(X,Y)=>{let s=poly([A,B,C].map(([x,y])=>[X(x),Y(y)]),'#eef2f3')+ln(X(-2),Y(0),X(8),Y(0),'#aab4bb',1,'3 3')+(v.line==='perpendicular'?ln(X(3),Y(-1),X(3),Y(6),alt,3):ln(X(C[0]),Y(C[1]),X(foot),Y(0),alt,3));if(v.line==='height'||v.line==='perpendicular')s+=poly([[X(foot),Y(0)],[X(foot)+9,Y(0)],[X(foot)+9,Y(0)-9],[X(foot),Y(0)-9]],'none',alt);if(v.line==='median'||v.line==='perpendicular')for(const x of [1.5,4.5])s+=ln(X(x),Y(0)-5,X(x),Y(0)+5,alt,2);if(v.line==='bisector'){const a=Math.atan2(Y(0)-Y(4),X(0)-X(v.x)),b=Math.atan2(Y(0)-Y(4),X(6)-X(v.x)),m=(a+b)/2,cx=X(v.x),cy=Y(4);for(const[start,end]of[[b,m],[m,a]]){s+='<path d="M'+(cx+25*Math.cos(start))+' '+(cy+25*Math.sin(start))+' A25 25 0 0 1 '+(cx+25*Math.cos(end))+' '+(cy+25*Math.sin(end))+'" fill="none" stroke="'+alt+'" stroke-width="2"/>';const mid=(start+end)/2;s+=dot(cx+25*Math.cos(mid),cy+25*Math.sin(mid),alt,2);}}return s;})+statement(v.line==='height'?'CF steht senkrecht auf der Geraden AB.':v.line==='median'?'AF = FB: CF verbindet C mit der Seitenmitte.':v.line==='perpendicular'?'AF = FB; die Linie durch F steht senkrecht auf AB.':'∠ACF = ∠FCB: CF halbiert den Winkel bei C.',(foot<0||foot>6?'F liegt auf der Verlängerung von AB. ':'F liegt auf der Seite AB. ')+(v.x===3?'Hier ist CA = CB; alle vier Linien fallen zusammen.':'Verschiebe C auf x = 3 und vergleiche die Linien.'));},'Die gewählte Eigenschaft bleibt beim Verschieben erhalten.','Höhe auch außerhalb; Winkelhalbierende mit Seitenverhältnissatz; Markierungen zeigen gleiche Winkel bzw. Seiten.');
  add('G08',[r('angle','C auf dem Halbkreis bewegen (Winkel bei M in Grad)',10,170,65)],'Welcher Winkel verändert sich beim Verschieben von C nicht?','AB ist der Durchmesser, M der Mittelpunkt. Die drei Strecken MA, MB und MC sind gleich lange Radien. Beobachte den markierten Winkel bei C.',v=>{const a=v.angle*Math.PI/180,C=[300+180*Math.cos(a),220-180*Math.sin(a)],A=[120,220],B=[480,220],u=[(A[0]-C[0])/Math.hypot(A[0]-C[0],A[1]-C[1]),(A[1]-C[1])/Math.hypot(A[0]-C[0],A[1]-C[1])],w=[(B[0]-C[0])/Math.hypot(B[0]-C[0],B[1]-C[1]),(B[1]-C[1])/Math.hypot(B[0]-C[0],B[1]-C[1])];return svg('<path d="M120 220 A180 180 0 0 1 480 220" fill="none" stroke="#aab5bc"/>'+poly([A,B,C],'#dce8ed44')+ln(300,220,...C,alt,2,'5 4')+dot(300,220,alt)+tx(300,243,'M',17,alt)+tx(210,235,'r',16,alt)+tx(390,235,'r',16,alt)+tx((300+C[0])/2+12,(220+C[1])/2,'r',16,alt)+poly([C,[C[0]+u[0]*16,C[1]+u[1]*16],[C[0]+(u[0]+w[0])*16,C[1]+(u[1]+w[1])*16],[C[0]+w[0]*16,C[1]+w[1]*16]],'none',alt)+tx(108,240,'A')+tx(492,240,'B')+tx(C[0],C[1]-15,'C'),'Thaleshalbkreis mit drei Radien und rechtem Winkel bei C',275)+statement('∠ACB = 90°','MA = MC und MB = MC: Die beiden kleinen Dreiecke sind gleichschenklig. Mit ihren gleichen Basiswinkeln und der Winkelsumme im großen Dreieck folgt der rechte Winkel bei C.');},'C bleibt auf dem Halbkreis mit Durchmesser AB.','Endpunkte ausgeschlossen; Radien als Grundlage der Begründung sichtbar.');
  add('G09',[r('depth','Tiefe des Quaders in cm',2,6,4),opt('view','Darstellung',[['net','Netz'],['oblique','Schrägbild']])],'Wo steckt dieselbe Tiefe in Netz und Schrägbild?','Das Netz zeigt echte Flächengrößen. Im Schrägbild werden Tiefenkanten hier halbiert gezeichnet.',v=>{let d=v.depth,s='';if(v.view==='net'){let u=17,x=170,y=40;for(let [a,b,w,h]of[[0,d,5,3],[5,d,d,3],[5+d,d,5,3],[-d,d,d,3],[0,0,5,d],[0,d+3,5,d]])s+=rect(x+a*u,y+b*u,w*u,h*u)+tx(x+(a+w/2)*u,y+(b+h/2)*u,`${w}×${h}`,13);}else{let A=[160,220],B=[360,220],C=[360,100],E=[160,100],dx=d*20/Math.SQRT2,dy=-dx; s=poly([A,B,C,E],'#fff')+poly([E,C,[C[0]+dx,C[1]+dy],[E[0]+dx,E[1]+dy]],tint)+poly([B,[B[0]+dx,B[1]+dy],[C[0]+dx,C[1]+dy],C],pale)+tx(275,245,'5 cm')+tx(125,160,'3 cm')+tx(440,150,`Tiefe ${d} cm`,15); }return svg(s,`Quader mit Maßen5×3×${d} als ${v.view==='net'?'Netz':'Schrägbild'}`,v.view==='net'?360:280)+statement(v.view==='net'?`6 Flächen: zweimal5×3, zweimal5×${d}, zweimal3×${d}.`:`Tiefenkante gezeichnet: ${f(d/2)} cm bei halber Tiefe.`);},'Dieselben sechs Rechtecke gehören zu demselben Quader.','Gültiges zusammenhängendes Netz; Schrägbild explizit mit halber Tiefenkantenlänge und45°-Richtung.');
  add('G10',[r('radius','Gemeinsamer Radius beider Kreise in cm',3.5,6,5,.5)],'Warum liegen beide Kreisschnittpunkte auf der Mittelsenkrechten von AB?','A und B liegen 6 cm auseinander. Verändere den Radius beider Kreise gleichzeitig. P und Q sind die Punkte, an denen sich die Kreislinien schneiden.',v=>{const radius=v.radius,h=Math.sqrt(radius*radius-9),X=x=>300+x*28,Y=y=>220-y*28;let s=circle(X(-3),Y(0),radius*28,ink)+circle(X(3),Y(0),radius*28,alt)+ln(X(-3),Y(0),X(3),Y(0),'#586974',2)+ln(X(0),35,X(0),405,'#687780',2,'5 4')+ln(X(-3),Y(0),X(0),Y(h),ink,3)+ln(X(3),Y(0),X(0),Y(h),alt,3)+poly([[X(0),Y(0)],[X(0)+11,Y(0)],[X(0)+11,Y(0)-11],[X(0),Y(0)-11]],'none','#586974');for(const x of [-1.5,1.5])s+=ln(X(x),Y(0)-5,X(x),Y(0)+5,'#586974',2);for(const[x,y,label,c]of[[-3,0,'A',ink],[3,0,'B',alt],[0,0,'M','#586974'],[0,h,'P',ink],[0,-h,'Q',ink]])s+=dot(X(x),Y(y),c,4)+tx(X(x)+(label==='P'||label==='Q'?16:0),Y(y)+(y===0?21:-14),label,18,c);s+=tx(X(-1.5),Y(0)+22,'3 cm',15)+tx(X(1.5),Y(0)+22,'3 cm',15)+tx(300,18,'Gestrichelt: Mittelsenkrechte von AB',16);return svg(s,'Zwei gleich große vollständige Kreise um A und B mit Schnittpunkten P und Q und Mittelpunkt M',430)+statement('PA = PB = '+f(radius)+' cm','P liegt auf beiden Kreislinien: PA und PB sind Radien. Dasselbe gilt für QA und QB.')+table(['Begründung','Folgerung'],[['PA = PB; AM = BM; PM ist gemeinsame Seite.','Die Dreiecke PAM und PBM sind kongruent (SSS).'],['Die beiden Winkel bei M sind gleich und ergeben zusammen 180°.','Jeder Winkel ist 90°: PM steht senkrecht auf AB.'],['M ist die Mitte von AB.','P liegt auf der Mittelsenkrechten. Für Q gilt dieselbe Begründung.']]);},'Beide Kreisschnittpunkte bleiben gleich weit von A und B entfernt.','Radius größer als die halbe Grundstrecke; beide vollständigen Kreise passen bei allen Einstellungen ins Bild.');
  add('M01',[r('v','Anzahl großer Einheiten',0,4,1.5,0.25),opt('unit','Größe',[['length','Meter → Zentimeter'],['mass','Kilogramm → Gramm'],['time','Stunden → Minuten'],['money','Euro → Cent']])],'Warum rechnest du bei Stunden anders um als bei Metern?','Die Größe bleibt unverändert, nur Maßzahl und Einheit wechseln.',v=>{let [a,b,k]=({length:['m','cm',100],mass:['kg','g',1000],time:['h','min',60],money:['€','ct',100]})[v.unit];return numberLine([[v.v,`${f(v.v)} ${a} = ${f(v.v*k)} ${b}`]],0,4,[],{step:.5,minor:.25})+table(['Große Einheit','Faktor','Kleine Einheit'],[[`1 ${a}`,`·${k}`,`${k} ${b}`],[`${f(v.v)} ${a}`,`·${k}`,`${f(v.v*k)} ${b}`]])+statement(`${f(v.v)} ${a} = ${f(v.v*k)} ${b}`,v.unit==='time'?'1,5 Stunden sind90 Minuten, nicht150 Minuten.':'Eine kleinere Einheit braucht eine größere Maßzahl für dieselbe Größe.');},'Die physikalische Größe bzw. der Geldbetrag bleibt gleich.','Zeit mit60, Masse mit1000, Länge und Geld mit100; null erlaubt.');
  add('M02',[opt('dim','Dimension',[[1,'Länge'],[2,'Fläche'],[3,'Volumen']],2),r('factor','Teile je Kantenlänge',2,10,10)],'Warum wird aus zehn bei einer Fläche hundert und beim Volumen tausend?','Zähle in jeder Richtung. Beim Volumen siehst du mehrere gleiche Schichten; jede enthält ein quadratisches Raster.',v=>{const n=v.factor,dim=+v.dim;let s;if(dim===1)s=bar(n,n,95,n+' gleich lange Abschnitte');else if(dim===2)s=grid(n,n,()=>true,210,210,195,35)+tx(300,17,n+' · '+n+' Flächenteile',17);else{ s='';for(let k=n-1;k>=0;k--)s+=poly([[175+k*12,100-k*7],[355+k*12,100-k*7],[355+k*12,280-k*7],[175+k*12,280-k*7]],'#f1f5f799','#8b9ca5');s+=grid(n,n,()=>true,180,180,175,100)+tx(300,17,n+' Schichten mit je '+n*n+' Würfeln',17)+tx(265,305,'Eine Schicht: '+n+' · '+n,17); }return svg(s,dim===3?'Volumen als Stapel quadratischer Würfelschichten':'Einteilung nach Dimension',dim===3?335:285)+statement(n+(dim>1?'<sup>'+dim+'</sup>':'')+' = '+n**dim+' '+(dim===1?'Streckenabschnitte':dim===2?'Flächenteile':'Raumteile'),n===10?'1 dm'+(dim===2?'²':dim===3?'³':'')+' = '+10**dim+' cm'+(dim===2?'²':dim===3?'³':''):'Der Faktor wirkt in jeder Richtung.');},'Jede neue Richtung multipliziert die Anzahl nochmals mit n.','Schichtenbild zeigt Tiefe zusätzlich zum Flächenraster; perspektivisch versetzt.');
  add('M03',[r('a','Breite a in cm',1,9,5),opt('mode','Vergleich',[['fixed','Höhe2cm'],['perimeter','Umfang20cm']])],'Können zwei Rechtecke denselben Umfang, aber verschiedene Flächen haben?','Randlänge und bedeckte Fläche sind verschiedene Größen.',v=>{let b=v.mode==='fixed'?2:10-v.a;return svg(grid(v.a,b,()=>true,v.a*22,b*22,200-v.a*5,25)+tx(300,245,`Rand U = ${2*(v.a+b)} cm · Fläche A = ${v.a*b} cm²`,20),'Rechteck mit Raster und Rand',280)+statement(`U = 2(${v.a} + ${b}) = ${2*(v.a+b)} cm; A = ${v.a} · ${b} = ${v.a*b} cm²`);},'Im Umfangmodus bleibta+b=10, der Flächeninhalt verändert sich.','Positive Rechteckseiten; Rand und Fläche mit unterschiedlichen Einheiten.');
  add('M04',[r('a','Länge in cm',2,6,4),r('b','Breite in cm',1,5,3),r('h','Höhe in cm',1,5,2),opt('open','Deckel',[[0,'Geschlossen'],[1,'Oben offen']])],'Was ändert ein fehlender Deckel an Oberfläche und Fassungsvermögen?','Volumen zählt den Rauminhalt. Die Oberfläche zählt die vorhandenen Außenflächen.',v=>{let w=v.a*32,h=v.h*32,d=v.b*16/Math.SQRT2,A=[110,230],B=[110+w,230],C=[110+w,230-h],E=[110,230-h],s=poly([A,B,C,E],tint)+poly([B,[B[0]+d,B[1]-d],[C[0]+d,C[1]-d],C],pale);if(!+v.open)s+=poly([E,C,[C[0]+d,C[1]-d],[E[0]+d,E[1]-d]],'#edf1f3');else s+=ln(E[0],E[1],E[0]+d,E[1]-d)+ln(E[0]+d,E[1]-d,C[0]+d,C[1]-d);let o=2*(v.a*v.b+v.a*v.h+v.b*v.h)-(+v.open?v.a*v.b:0);s+=tx(110+w/2,249,'a = '+v.a+' cm',16)+tx(87,230-h/2,'h = '+v.h,16)+tx(110+w+d+16,230-h/2-d/2,'b = '+v.b+' cm',16,alt,'start');return svg(s,'Quader mit veränderbaren Maßen und optionalem Deckel',270)+statement(`V = ${v.a} · ${v.b} · ${v.h} = ${v.a*v.b*v.h} cm³<br>O = ${o} cm²`,+v.open?`Die Deckelfläche ${v.a*v.b} cm² fehlt; das Volumen bleibt gleich.`:'Drei Paare von Rechtecken bilden die Oberfläche.');},'Beim Entfernen des Deckels bleibt Volumen unverändert; eine Fläche fällt weg.','Alle Maße positiv; Oberfläche offener Behälter korrekt angepasst.');
  add('M05',[r('shift','Spitze seitlich verschieben',-2,8,3,0.5),r('h','Senkrechte Höhe in cm',1,5,3)],'Ändert eine seitliche Verschiebung der Spitze die Dreiecksfläche?','Die Grundseite bleibt6cm. Entscheidend ist die senkrechte Höhe, nicht die schräge Seitenlänge.',v=>{let X=x=>110+x*36,Y=y=>225-y*36;return svg(poly([[X(0),Y(0)],[X(6),Y(0)],[X(v.shift),Y(v.h)]])+ln(X(v.shift),Y(v.h),X(v.shift),Y(0),alt,3,'5 3')+ln(X(-2),Y(0),X(8),Y(0),'#aeb9bf',1)+tx(X(3),245,'6 cm')+tx(X(v.shift)+16,Y(v.h/2),`${v.h} cm`,18,alt,'start'),'Dreieck mit fester Grundseite und senkrechter Höhe',275)+statement(`A = ½ · 6 · ${v.h} = ${3*v.h} cm²`,'Die Höhe darf auf der Verlängerung der Grundseite stehen.');},'Seitliches Schieben bei fester Höhe erhält die Fläche.','Höhenfuß auch außerhalb; positive Höhe, keine Messung der schrägen Seite als Höhe.');
  add('M06',[r('h','Prismenhöhe in cm',1,8,3)],'Wie verändern zusätzliche gleiche Schichten das Volumen und den Mantel?','Die Grundfläche ist ein rechtwinkliges3–4–5-Dreieck: G=6cm², Umfang u=12cm.',v=>{let s='';for(let k=v.h;k>=0;k--)s+=poly([[150+k*13,220-k*12],[310+k*13,220-k*12],[150+k*13,100-k*12]],k===0?tint:'#eaf0f455',k===0?ink:'#8e9da6');s+=tx(230,242,'4 cm',16)+tx(122,160,'3 cm',16)+ln(310,220,310+v.h*13,220-v.h*12,alt,3)+tx(350+v.h*13,210-v.h*6,'h = '+v.h+' cm',16,alt);return svg(s,'Dreiecksprisma aus gleichen Schichten',275)+statement(`V = 6 · ${v.h} = ${6*v.h} cm³<br>M = 12 · ${v.h} = ${12*v.h} cm²<br>O = 2 · 6 + ${12*v.h} = ${12+12*v.h} cm²`,'Die beiden Grundflächen bleiben gleich groß; jede zusätzliche1-cm-Schicht vergrößert das Volumen um6cm³.');},'Grundfläche und Grundumfang bleiben konstant.','Gerades Prisma; Prismenhöhe von Dreieckshöhe getrennt.');
  add('M07',[r('n','Maßstabszahl n bei1:n',20,200,100,20),r('draw','Länge im Plan in cm',1,5,3)],'Wird die Wirklichkeit größer oder kleiner, wenn n bei gleicher Planlänge wächst?','Beide Längen werden zuerst in derselben Einheit verglichen.',v=>svg(ln(100,70,500,70,'#b6c1c6')+ln(100,70,100+v.draw*80,70,ink,6)+tx(300,25,`Plan: ${v.draw} cm`,20)+Array.from({length:6},(_,i)=>ln(100+i*80,63,100+i*80,77,'#72848e')+tx(100+i*80,95,`${i} cm`,12)).join('')+ln(100,185,500,185,'#b6c1c6')+ln(100,185,100+v.draw*v.n/100*40,185,alt,6)+tx(300,145,`Wirklichkeit: ${v.draw*v.n} cm = ${f(v.draw*v.n/100)} m`,20,alt)+Array.from({length:6},(_,i)=>ln(100+i*80,178,100+i*80,192,'#72848e')+tx(100+i*80,211,`${i*2} m`,12)).join(''),'Zwei feste, ausdrücklich beschriftete Skalen für Plan und Wirklichkeit')+statement(`${v.draw} cm · ${v.n} = ${v.draw*v.n} cm`,'Die beiden Strecken verwenden verschiedene Skalen. Ein1-cm-Abschnitt im Plan steht für ncm in der Wirklichkeit.'),'Das Verhältnis Plan/Wirklichkeit ist1/n.','Getrennte Bildskalen ausdrücklich benannt; keine gleich langen echten Strecken suggeriert.');
  add('M08',[r('l','Aquariumlänge in cm',40,100,80,10),r('h','Wasserhöhe in cm',10,50,30,5)],'Welche Größenordnung erwartest du, bevor du die Einheiten umrechnest?','Das Bild zeigt das Aquarium von der Seite. Die Breite von 40 cm geht in die Tiefe und ist hier nicht sichtbar. 1000 cm³ entsprechen 1 Liter.',v=>{let volume=v.l*40*v.h,rough=Math.round(v.l/10)*Math.round(v.h/10)*4;return svg(rect(95,25,v.l*4,200,'#fff')+rect(95,225-v.h*4,v.l*4,v.h*4,tint)+tx(300,250,`${v.l}cm × 40cm × ${v.h}cm Wasser`,20),'Aquarium als Größenordnungsmodell',285)+statement(`${volume.toLocaleString('de-DE')} cm³ = ${volume/1000} Liter`,`In Dezimetern: ${f(v.l/10)} · 4 · ${f(v.h/10)} dm³. Grober Überschlag mit ganzen dm: etwa ${rough} Liter.`);},'Dieselbe Wassermenge wird in cm³ und Litern beschrieben.','Wasserhöhe maximal50cm; Überschlag als ungefähr gekennzeichnet; Raummaß korrekt1000cm³/L.');

  add('S01',[r('share','Anteil der Befragten am Fahrradständer in Prozent',0,100,80,10)],'Kann eine große, aber einseitige Stichprobe eine ganze Schule vertreten?','Im Beispiel fahren am Fahrradständer90% Rad, in der übrigen Auswahl30%. Die Mischung beeinflusst das Ergebnis.',v=>{let p=.9*v.share+.3*(100-v.share);return svg(bar(v.share,100,65,`${v.share}% Fahrradständer-Auswahl`)+bar(Math.round(p),100,155,`Beobachteter Radanteil: ${f(p)}%`,alt),'Zusammensetzung der Stichprobe und daraus entstehender Anteil')+statement(`Beobachteter Anteil = ${f(p)}%`,'Diese bewusst vereinfachten Beispielgruppen zeigen Auswahlverzerrung. Mehr Personen aus derselben einseitigen Auswahl beseitigen sie nicht. Für die ganze Schule fehlt eine passende Zufallsauswahl.');},'Die Beispielanteile innerhalb der Gruppen bleiben; nur die Auswahlmischung ändert sich.','Didaktische Beispieldaten ausdrücklich markiert, keine echten Schuldaten/Schätzung behauptet.');
  add('S02',[r('h','Treffer h',0,20,6),r('n','Gesamtzahl N',20,60,24,2)],'Wie verändert sich der Anteil, wenn die Trefferzahl gleich bleibt, aber die Gruppe wächst?','Die absolute Häufigkeit zählt; die relative Häufigkeit berücksichtigt die Gesamtzahl.',v=>svg(bar(v.h,v.n,95,`${v.h} von ${v.n}`),'Anzahl Treffer im Verhältnis zur Gesamtgruppe')+statement(`r = ${v.h}/${v.n} = ${reduced(v.h,v.n)} ≈ ${f(v.h/v.n*100)}%`),'Bei festem h sinkt h/N mit größerem N.','N≥20≥h, somit gültige Häufigkeiten; keine Division durch null.');
  add('S03',[r('start','Beginn der y-Achse',0,3,0)],'Wirken dieselben Daten bei einem anderen Achsenbeginn dramatischer?','Die Zahlen bleiben10,6 und4. Die sichtbaren Balkenhöhen hängen auch vom Achsenanfang ab.',v=>{let s=ln(100,220,520,220)+ln(100,220,100,25);for(let y=v.start;y<=10;y++)s+=tx(78,220-(y-v.start)/(10-v.start)*180,y,13)+ln(100,220-(y-v.start)/(10-v.start)*180,520,220-(y-v.start)/(10-v.start)*180,'#e6ebed',1);[10,6,4].forEach((n,i)=>s+=rect(155+i*130,220-(n-v.start)/(10-v.start)*180,65,(n-v.start)/(10-v.start)*180)+tx(187+i*130,240,'ABC'[i])+tx(187+i*130,205-(n-v.start)/(10-v.start)*180,n,16));return svg(s,'Identische Daten bei veränderlichem Achsenbeginn',270)+statement(`Tatsächliches Verhältnis A:C = 10:4 = 2,5:1`,v.start?`Sichtbare Höhen: ${10-v.start}:${4-v.start}. Die abgeschnittene Achse lässt den Unterschied stärker wirken.`:'Die Achse beginnt bei0; die Balkenhöhen bilden die Mengenverhältnisse ab.');},'Daten und Kategorien bleiben identisch; nur die Darstellung verändert sich.','Achse beginnt höchstens bei3 unter dem kleinsten Wert4; Schnitt kenntlich beschriftet.');
  add('S04',[r('last','Letzten Datenwert verändern',4,20,8)],'Welcher Kennwert reagiert besonders stark auf einen hohen Einzelwert?','Beobachte dieselbe Datenreihe2,3,3,4 und einen veränderlichen letzten Wert.',v=>{let a=[2,3,3,4,v.last],mean=a.reduce((s,x)=>s+x,0)/5;return svg(barAxis(20,220,9,5)+a.map((n,i)=>rect(80+i*90,220-n*9,50,n*9)+tx(105+i*90,240,n)).join('')+ln(60,220-mean*9,550,220-mean*9,alt,2,'5 4')+tx(500,205-mean*9,`Mittel ${f(mean)}`,15,alt),'Datenwerte mit gemeinsamer Skala und Mittelwertlinie',270)+statement(`Mittelwert = ${f(mean)} · Modalwert${v.last===4?'e = 3 und4':' = 3'} · Spannweite = ${v.last-2}`);},'Die ersten vier Datenwerte bleiben; der letzte Wert beeinflusst Mittel und Spannweite.','Bei letztem Wert4 zwei Modalwerte korrekt; Wiederholungen mitgezählt.');
  add('S05',[r('spread','Abstand der äußeren Werte vom Mittel',0,4,3)],'Wie können sich die Daten stark ändern, obwohl der Durchschnitt gleich bleibt?','Werte können sich vom Mittel wegbewegen und ihre Änderungen gegenseitig ausgleichen.',v=>{let a=[4-v.spread,4-v.spread/2,4,4+v.spread/2,4+v.spread];return svg(barAxis(8,225,24,2)+a.map((n,i)=>rect(70+i*100,225-n*24,65,n*24)+tx(102+i*100,245,f(n))).join('')+ln(50,129,550,129,alt,3,'5 4')+tx(520,113,'Mittel4',15,alt),'Veränderte Verteilung mit konstantem Mittelwert',275)+statement(`Mittelwert = 4 · Spannweite = ${2*v.spread}`,`Daten: ${a.map(x=>f(x)).join('; ')}. Die Summe bleibt20.`);},'Die Summe und damit das Mittel bleiben konstant, die Spannweite wächst.','Nichtnegative Daten0–8; Mittelwert und Streuung bewusst entkoppelt.');

  function rng(seed){let a=(seed+1000)>>>0;return()=>{a=(Math.imul(1664525,a)+1013904223)>>>0;return a/4294967296;};}
  function simulation(n,p,seed){let random=rng(seed),hit=0,trace=[];for(let i=1;i<=n;i++){if(random()<p)hit++;trace.push([i,hit/i]);}return{hit,trace};}
  function frequencyGraph(series,p,n){let body=ln(50,225,550,225)+ln(50,225,50,25);for(let i=0;i<=4;i++)body+=tx(32,225-i*50,`${i*25}%`,11)+ln(50,225-i*50,550,225-i*50,'#e2e8eb',1);for(const tick of PlotScale.ticks(0,n,Math.max(1,PlotScale.step(0,n,5))))body+=ln(50+tick/n*500,225,50+tick/n*500,230)+`<g data-axis="count" data-tick="${tick}">${tx(50+tick/n*500,248,String(tick),13)}</g>`;body+=ln(50,225-p*200,550,225-p*200,alt,2,'5 4')+`<polyline points="${series.map(([x,y])=>`${50+x/n*500},${225-y*200}`).join(' ')}" fill="none" stroke="${ink}" stroke-width="2"/>`+tx(300,270,'Anzahl der Versuche',13)+tx(495,14,`Modell: ${f(p*100)}%`,15,alt);return svg(body,'Kumulative relative Häufigkeit und feste Modellwahrscheinlichkeit',295);}
  add('W01',[opt('event','Ereignis',[['even','Gerade Augenzahl'],['greater','Größer als4'],['sure','Kleiner als7'],['impossible','Augenzahl8']]),r('result','Beobachtetes Ergebnis',1,6,4)],'Was unterscheidet das einzelne Ergebnis vom Ereignis?','Ein Ereignis ist eine Menge passender Ergebnisse. Es tritt ein, wenn das beobachtete Ergebnis zur Menge gehört.',v=>{let set=({even:[2,4,6],greater:[5,6],sure:[1,2,3,4,5,6],impossible:[]})[v.event];return svg([1,2,3,4,5,6].map((n,i)=>rect(60+i*80,60,65,65,set.includes(n)?tint:'#fff')+tx(92+i*80,92,n,25)+ (n===v.result?tx(92+i*80,155,'↑',27,alt):'')).join('')+tx(300,205,'Pfeil: beobachtetes Ergebnis',18,alt),'Ergebnismenge eines Würfels und ausgewähltes Ereignis')+statement(`E = ${set.length?'{'+set.join('; ')+'}':'∅'}`,set.includes(v.result)?`Ergebnis${v.result} liegt in E: Das Ereignis tritt ein.`:`Ergebnis${v.result} liegt nicht in E: Das Ereignis tritt nicht ein.`);},'Die Ergebnismenge bleibt{1,…,6}; Ereignis ist eine Teilmenge.','Sicheres und unmögliches Ereignis sowie Grenzfall>4 explizit.');
  add('W02',[r('red','Rote Kugeln',1,8,3),r('blue','Blaue Kugeln',1,8,1)],'Bedeuten zwei Farben automatisch je50% Chance?','Alle einzelnen Kugeln sind gleich wahrscheinlich, die Farbnamen müssen es nicht sein.',v=>{let total=v.red+v.blue;return svg(Array.from({length:total},(_,i)=>dot(70+i%8*65,75+Math.floor(i/8)*80,i<v.red?alt:ink,20)+tx(70+i%8*65,75+Math.floor(i/8)*80,i<v.red?'R':'B',16,'#fff')).join(''),'Einzelne gleich wahrscheinliche Kugeln in zwei Farben')+statement(`P(R) = ${v.red}/${total}; P(nicht R) = ${v.blue}/${total}`,`Zusammen: (${v.red}+${v.blue})/${total} = 1. ${v.red===v.blue?'Hier sind beide Farben gleich wahrscheinlich.':'Die beiden Farben haben unterschiedliche Chancen.'}`);},'Ereignis und Gegenereignis ergänzen sich zur gesamten Urne.','Mindestens eine Kugel jeder Farbe; gleichartige Kugeln als Laplace-Einzelergebnisse.');
  add('W03',[r('n','Anzahl der Münzwürfe',10,500,100,10),r('seed','Andere Beispielserie',1,20,1)],'Wird der Abstand zum Modell mit jedem einzelnen Wurf kleiner?','Die Linie zeigt eine simulierte Serie einer fairen Münze; die Modellchance bleibt50%.',v=>{let s=simulation(v.n,.5,v.seed);return frequencyGraph(s.trace,.5,v.n)+statement(`${s.hit} von ${v.n} Würfen: ${f(s.hit/v.n*100)}% Kopf`,'Die relative Häufigkeit schwankt. Der nächste unabhängige Wurf hat weiterhin50% Kopfchance und gleicht nichts absichtlich aus.');},'Modellchance0,5 bleibt fest; Versuchszahl verändert die beobachtete Häufigkeit.','Reproduzierbare Pseudozufallsserien; kein monotones Näherkommen oder exaktes50%-Ergebnis versprochen.');
  function tree(pr,pAfterR,pAfterB,selected=[]){let s=dot(65,140),nodes=[[240,70,'R',pr],[240,210,'B',1-pr]],ends=[[455,35,'RR',pAfterR],[455,105,'RB',1-pAfterR],[455,175,'BR',pAfterB],[455,245,'BB',1-pAfterB]];nodes.forEach(([x,y,l,p])=>s+=ln(65,140,x,y)+dot(x,y)+tx(148,(140+y)/2-14,`${f(p*100,1)}%`,15)+tx(x,y-20,l));ends.forEach(([x,y,l,p],i)=>{let n=nodes[i<2?0:1],color=selected.includes(l)?alt:ink;s+=ln(n[0],n[1],x,y,color,selected.includes(l)?4:2)+dot(x,y,color)+tx(345,(n[1]+y)/2-12,`${f(p*100,1)}%`,14,color)+tx(488,y,l,17,color);});return svg(s,'Baumdiagramm mit zwei Stufen und beschrifteten Zweigwahrscheinlichkeiten',285);}
  add('W04',[r('red','Rote Kugeln',1,5,2),r('blue','Blaue Kugeln',1,5,1),opt('replace','Nach dem ersten Zug',[[1,'Mit Zurücklegen'],[0,'Ohne Zurücklegen']],0)],'Warum ändern sich ohne Zurücklegen die Zahlen im zweiten Zug?','Vor jedem Zweig zählt die tatsächlich noch vorhandene Urne.',v=>{let n=v.red+v.blue,back=+v.replace,pr=v.red/n,ar=back?pr:(v.red-1)/(n-1),ab=back?pr:v.red/(n-1);return tree(pr,ar,ab)+statement(`Nach Rot: ${back?v.red:v.red-1}R + ${v.blue}B; nach Blau: ${v.red}R + ${back?v.blue:v.blue-1}B`,'An jedem Knoten ergeben die beiden Zweigwahrscheinlichkeiten zusammen100%. R=Rot, B=Blau.');},'Zweigsumme an jedem Knoten1; Zurücklegen entscheidet über konstante oder geänderte Urne.','Mindestens zwei Kugeln; unmögliche Zweige mit0% sichtbar, kein Nenner0.');
  add('W05',[r('p','Chance für Rot je Zug in Prozent',10,90,50,10),opt('event','Ereignis',[['exact','Genau einmal Rot'],['atleast','Mindestens einmal Rot'],['both','Zweimal Rot']])],'Welche vollständigen Pfade gehören zum Ereignis?','Unabhängige Züge mit Zurücklegen: entlang eines Pfades multiplizieren, passende Pfade addieren.',v=>{let p=v.p/100,all={RR:p*p,RB:p*(1-p),BR:(1-p)*p,BB:(1-p)**2},sel=({exact:['RB','BR'],atleast:['RR','RB','BR'],both:['RR']})[v.event],sum=sel.reduce((s,k)=>s+all[k],0);return tree(p,p,p,sel)+statement(`${sel.map(k=>`P(${k})`).join(' + ')} = ${sel.map(k=>f(all[k])).join(' + ')} = ${f(sum)}`,`Beispielpfad RB: ${f(p)} · ${f(1-p)} = ${f(all.RB)}. R=Rot, B=Blau.`);},'Pfadwahrscheinlichkeiten aller vier vollständigen Pfade ergeben1.','Mit Zurücklegen und Unabhängigkeit explizit; keine Doppelzählung, genau/mindestens unterschieden.');
  add('W06',[r('digits','Wie viele Ziffern0–9 zählen als Treffer?',1,9,3),r('n','Anzahl der Versuche',20,500,100,20),r('seed','Andere Beispielserie',1,20,1)],'Welche Zuordnung bildet30% Trefferchance ab?','Jede Ziffer0–9 hat dieselbe Chance. Die vorab festgelegte Trefferregel bestimmt das Modell.',v=>{let rand=rng(v.seed+200),hit=0,trace=[],first=[];for(let i=1;i<=v.n;i++){let d=Math.floor(rand()*10);if(i<=12)first.push(d);if(d<v.digits)hit++;trace.push([i,hit/i]);}return table(['Trefferziffern','Modellchance','Erste12 Zufallsziffern'],[[Array.from({length:v.digits},(_,i)=>i).join(', '),`${v.digits}/10 = ${v.digits*10}%`,first.map(d=>`<span style="${d<v.digits?'font-weight:bold;text-decoration:underline':''}">${d}</span>`).join(' ')]])+frequencyGraph(trace,v.digits/10,v.n)+statement(`${hit} Treffer aus ${v.n}: ${f(hit/v.n*100)}%`,'Ein Versuch ist eine Zufallsziffer. Ändert sich die Trefferregel, wird die gezeigte Serie als neues Modell ausgewertet; die Chance wird nicht nachträglich an ein gewünschtes Ergebnis angepasst.');},'Bei fester Regel ist die Modellchance fest; die Serie darf davon abweichen.','Pseudozufall, ganzzahlige gleichgewichtete0–9; Regel und Versuchszahl explizit.');
  return D;
})();
if (typeof module !== 'undefined' && module.exports) module.exports = DISCOVERIES;

